INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'B1.1', 9, 'Time Clauses: als vs. wenn', 'Temporale Nebensätze: als, wenn, bevor, nachdem, während, bis, seit', 'temporal-clauses', 'Master als vs. wenn, bevor, nachdem (plus the Plusquamperfekt), während, bis and seit for putting events in order. telc B1 rewards this in Sprachbausteine Teil 1, the halbformelle Brief in Schreiben, Sprechen Teil 1-3 and Hören Teil 2.', 'Lerne als vs. wenn, bevor, nachdem (mit Plusquamperfekt), während, bis und seit — die Konnektoren für die richtige Reihenfolge. Die telc-Prüfung B1 prüft das in den Sprachbausteinen, im halbformellen Brief, in Sprechen und in Hören Teil 2.', 23, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['subordinating-conjunctions','subordinate-word-order','simple-past-sein-haben']::text[], ARRAY['subordinating-conjunctions','simple-past-narrative','perfect-tense-haben','temporal-prepositions']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'B1.1', 10, 'obwohl, damit, sodass & falls', 'Nebensätze mit obwohl, damit, sodass und falls', 'obwohl-damit-sodass', 'obwohl, damit, um … zu, sodass and falls connect two ideas in one sentence. obwohl marks a contrast, damit and um … zu a purpose, sodass a result and falls a condition. You need all four in telc B1 Sprachbausteine Teil 1, the halbformeller Brief, and Sprechen Teil 2.', 'obwohl, damit, um … zu, sodass und falls verbinden zwei Ideen in einem Satz. obwohl zeigt einen Gegensatz, damit und um … zu einen Zweck, sodass eine Folge und falls eine Bedingung. Du brauchst sie in den Sprachbausteinen, im halbformellen Brief und in Sprechen Teil 2.', 24, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['subordinating-conjunctions','subordinate-word-order','um-zu-ohne-zu']::text[], ARRAY['um-zu-ohne-zu','subordinating-conjunctions','subordinate-word-order','advanced-conjunctions']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'B1.1', 11, 'Connectors with Inversion', 'Konnektoren mit Inversion: deshalb, trotzdem, außerdem, sonst', 'adverbial-connectors', 'Link two ideas without a Nebensatz: deshalb, trotzdem, außerdem, sonst, dann, danach, dabei and dagegen open (or sit inside) a normal main clause, so the verb only moves to position 2 — never to the end. telc B1 tests this in Sprachbausteine Teil 1, in the halbformeller Brief (Schreiben) and whenever you justify an opinion in Sprechen Teil 2–3.', 'Verbinde zwei Ideen ohne Nebensatz: deshalb, trotzdem, außerdem, sonst, dann, danach, dabei und dagegen eröffnen einen Hauptsatz. Das Verb bleibt auf Position 2, nicht am Ende. Du brauchst das im telc B1: Sprachbausteine Teil 1, Schreiben (halbformeller Brief) und Sprechen Teil 2–3.', 24, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['coordinating-conjunctions','subordinating-conjunctions','subordinate-word-order']::text[], ARRAY['coordinating-conjunctions','subordinating-conjunctions','advanced-conjunctions']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'B1.1', 12, 'Two-Part Connectors', 'Zweiteilige Konnektoren: entweder … oder, nicht nur … sondern auch', 'two-part-connectors', 'Connect ideas with five two-part connector pairs: entweder … oder, nicht nur … sondern auch, sowohl … als auch, weder … noch and zwar … aber. Learn what each pair connects and how word order shifts after the first part. The telc B1 exam rewards this in Sprachbausteine Teil 1, in Schreiben when you make suggestions, and in Sprechen Teil 2 when you weigh Vor- und Nachteile.', 'Verbinde Ideen mit fünf zweiteiligen Konnektoren: entweder … oder, nicht nur … sondern auch. Weitere Paare: sowohl … als auch, weder … noch, zwar … aber. Lerne, was jedes Paar verbindet und wie sich die Wortstellung ändert. Die telc-B1-Prüfung braucht das in Sprachbausteine Teil 1, beim Schreiben von Vorschlägen und beim Sprechen: Vor- und Nachteile.', 22, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['coordinating-conjunctions','subordinate-word-order']::text[], ARRAY['coordinating-conjunctions','advanced-conjunctions','subordinate-word-order','subordinating-conjunctions']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid);

-- Rules
INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f4e57582-25f5-55dd-b738-7c9404de50dc'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'introduction', 'Temporal Clauses: Introduction', 'Einführung: Temporale Nebensätze', '{"hook_de":"Bevor ich zur Arbeit fahre, trinke ich einen Kaffee.","hook_en":"Bevor ich zur Arbeit fahre, trinke ich einen Kaffee — before I drive to work, I drink a coffee. Temporal clauses put two events in order.","scenario_en":"Telling a story at work, describing your daily routine, or explaining the steps in an official process.","preview_note_en":"Every connector here sends the verb to the end of its clause — the same rule you already know from weil and dass.","preview_highlight":"als, wenn, bevor, nachdem, während, bis, seit","preview_example_de":"Nachdem ich die Prüfung bestanden habe, feiere ich mit meiner Familie.","preview_example_en":"After I pass the exam, I celebrate with my family.","why_it_matters_en":"telc B1 Sprechen Teil 1-2 asks you to describe your day or an experience in order, Schreiben rewards a clear Ablauf, and Hören Teil 2 tests whether you understood the correct sequence of events.","german_difference_en":"English often uses one simple past tense for a finished story; German chooses between als and wenn, and nachdem even needs an earlier tense, the Plusquamperfekt.","english_comparison_en":"English: When I arrived, I called my sister. German splits als (one past event) from wenn (present, future or repeated) — a distinction English does not make."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f4e57582-25f5-55dd-b738-7c9404de50dc'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '6819e3cb-7210-54c3-b942-e9bc3206f09f'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'table', 'als vs. wenn: The Key Difference', 'als vs. wenn: Der wichtigste Unterschied', '{"type":"case_table","headers":["Regel","Beispiel","English"],"rows":[["als: ein einmaliges Ereignis in der Vergangenheit","Als ich zum ersten Interview kam, war ich sehr nervös.","als: one single event in the past"],["wenn: Gegenwart oder Zukunft","Wenn ich Stress habe, gehe ich abends spazieren.","wenn: present or future"],["wenn: wiederholt in der Vergangenheit (jedes Mal)","Jedes Mal, wenn er kam, brachte er Blumen mit.","wenn: repeated in the past (every time)"],["Nicht als für Wiederholungen!","Falsch: Als er kam, brachte er oft Blumen mit. Richtig: Wenn er kam, brachte er oft Blumen mit.","als is never used for something repeated"]],"highlight_row":-1,"description_de":"als steht nur für ein Ereignis, das genau einmal passiert ist. Bei allem anderen — Gegenwart, Zukunft oder Wiederholung — steht wenn.","description_en":"als is reserved for one event that happened exactly once. Everything else — present, future or repetition — takes wenn."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Only one past event? als. More than one, or not finished yet? wenn.', 'Nur ein Ereignis in der Vergangenheit? als. Alles andere: wenn.', NULL, NULL, 'als and wenn both send the verb to the end — the difference is only about WHEN and HOW OFTEN, never about word order.', 'als und wenn schicken beide das Verb ans Ende. Der Unterschied betrifft nur WANN und WIE OFT, nie die Wortstellung.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '6819e3cb-7210-54c3-b942-e9bc3206f09f'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f91fde99-08a4-5205-935a-060da737e76a'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'pattern', 'bevor and nachdem: Building the Sentence', 'bevor und nachdem: So baust du den Satz', '{"type":"steps","steps":[{"step":1,"title_de":"Bestimme die Reihenfolge.","title_en":"Decide the order of events.","detail_de":"bevor: Das Ereignis im Nebensatz kommt später. nachdem: Das Ereignis im Nebensatz kommt zuerst.","detail_en":"bevor: the event in the subordinate clause happens later. nachdem: it happens first."},{"step":2,"title_de":"Setze das Verb ans Ende.","title_en":"Send the verb to the end.","detail_de":"Bevor ich unterschreibe, lese ich den Vertrag. unterschreibe steht im Nebensatz ganz am Ende.","detail_en":"Bevor ich unterschreibe, lese ich den Vertrag. unterschreibe stands at the end of the bevor-clause."},{"step":3,"title_de":"Wähle die Position: Nebensatz zuerst oder Hauptsatz zuerst.","title_en":"Choose the order: subordinate clause first or main clause first.","detail_de":"Nebensatz zuerst: Komma, dann Verb, dann Subjekt. Hauptsatz zuerst: das Komma steht direkt vor bevor/nachdem.","detail_en":"Subordinate clause first: comma, then verb, then subject. Main clause first: the comma comes right before bevor/nachdem."},{"step":4,"title_de":"Setz das Komma richtig.","title_en":"Place the comma correctly.","detail_de":"Vor bevor und nachdem steht immer ein Komma — egal, wo der Nebensatz steht.","detail_en":"A comma always comes before bevor and nachdem, no matter where the clause stands."}],"description_de":"Diese vier Schritte funktionieren für bevor und nachdem auf die gleiche Weise.","description_en":"These four steps work the same way for both bevor and nachdem."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'If the subordinate clause comes first, the verb of the main clause follows immediately after the comma — no extra word in between.', 'Steht der Nebensatz zuerst, folgt direkt nach dem Komma das Verb des Hauptsatzes — kein Wort dazwischen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f91fde99-08a4-5205-935a-060da737e76a'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1ebd2007-99f6-5d37-8b19-19315cb93950'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'table', 'nachdem + Plusquamperfekt: One Step Earlier', 'nachdem + Plusquamperfekt: Eine Zeitstufe früher', '{"type":"case_table","headers":["Hauptsatz-Zeit","nachdem-Satz-Zeit","Beispiel"],"rows":[["Präsens (Gegenwart/Zukunft)","Perfekt","Nachdem ich die Prüfung bestanden habe, feiere ich mit meiner Familie."],["Präteritum (Erzählung)","Plusquamperfekt","Nachdem sie die Kündigung bekommen hatte, ging sie zum Arbeitsamt."],["Bildung: hatte/war + Partizip II","nur im nachdem-Satz","Nachdem er gegessen hatte, ging er schlafen."]],"highlight_row":-1,"description_de":"Der nachdem-Satz ist immer eine Zeitstufe früher als der Hauptsatz: Perfekt vor Präsens, Plusquamperfekt vor Präteritum.","description_en":"The nachdem-clause is always one tense-step earlier than the main clause: Perfekt before Präsens, Plusquamperfekt before Präteritum."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'Plusquamperfekt at B1.1 belongs only in a nachdem-clause — you don''t use it anywhere else yet.', 'Das Plusquamperfekt gehört auf diesem Niveau nur in den nachdem-Satz — sonst benutzt du es noch nicht.', 'Ask yourself: is the main clause Präsens or Präteritum? That answer decides Perfekt or Plusquamperfekt in the nachdem-clause.', 'Frag dich: Steht der Hauptsatz im Präsens oder im Präteritum? Das entscheidet über Perfekt oder Plusquamperfekt im nachdem-Satz.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1ebd2007-99f6-5d37-8b19-19315cb93950'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '5de9501f-622c-5a4a-9521-2dc4b1d2fd46'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'tip', 'während, bis, seit: while, until, since', 'während, bis, seit/seitdem', '{"content_de":"während beschreibt zwei Dinge gleichzeitig: Während ich warte, lese ich. bis beschreibt ein Ende: Ich warte, bis der Bus kommt. seit/seitdem beschreibt einen Start in der Vergangenheit mit Wirkung bis heute: Seit ich hier wohne, kenne ich alle Nachbarn.","content_en":"während describes two things at the same time: Während ich warte, lese ich (while I wait, I read). bis marks an endpoint: Ich warte, bis der Bus kommt (I wait until the bus comes). seit/seitdem marks a start in the past that still matters today: Seit ich hier wohne, kenne ich alle Nachbarn (since I''ve lived here, I know all the neighbours)."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'sobald means ''as soon as'' and works like wenn — the sobald-event happens first. At B1.1 you only need to recognise it, not use it yourself.', 'sobald bedeutet „sofort wenn“ und funktioniert wie wenn: Das sobald-Ereignis passiert zuerst. Auf diesem Niveau musst du es nur verstehen.', 'während, bis and seit all send the verb straight to the end, exactly like every other connector in this lesson.', 'während, bis und seit schicken das Verb ans Ende, genau wie jeder andere Konnektor in dieser Lektion.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '5de9501f-622c-5a4a-9521-2dc4b1d2fd46'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0befa628-21a1-5c9f-8df1-51e34527a573'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'explanation_comparison', 'All the Connectors at a Glance', 'Alle Konnektoren im Überblick', '{"type":"case_table","headers":["Konnektor","Bedeutung","Beispiel"],"rows":[["als","ein einmaliges Ereignis (Vergangenheit)","Als ich zur Party kam, war die Musik schon laut."],["wenn","Gegenwart, Zukunft oder Wiederholung","Wenn ich Zeit habe, rufe ich dich an."],["bevor","vorher (früheres Ereignis)","Bevor ich einkaufen gehe, schreibe ich eine Liste."],["nachdem","danach (Vorzeitigkeit im Nebensatz)","Nachdem ich gegessen habe, räume ich die Küche auf."],["während","gleichzeitig","Während ich koche, hört mein Mann Musik."],["bis","bis zu einem Endpunkt","Wir bleiben, bis der Regen aufhört."],["seit/seitdem","Start in der Vergangenheit, Wirkung bis heute","Seit ich Deutsch lerne, lese ich jeden Tag."]],"highlight_row":-1,"description_de":"Sieben Konnektoren, eine Regel: Das Verb steht immer am Ende des Nebensatzes.","description_en":"Seven connectors, one rule: the verb always stands at the end of the subordinate clause."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Once you know one temporal connector''s word order, you know all seven — only the meaning changes.', 'Kennst du die Wortstellung bei einem temporalen Konnektor, kennst du sie bei allen sieben — nur die Bedeutung ändert sich.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0befa628-21a1-5c9f-8df1-51e34527a573'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'afc414bf-b17e-5b66-8164-b0a2118be1db'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'dialogue', 'Dialogue: The New Job', 'Dialog: Der neue Job', '{"speakers":["Anna","Markus"],"exchanges":[{"speaker":"Anna","text_de":"Seit wann arbeitest du schon hier?","text_en":"How long have you already been working here?","grammar_note":"seit wann fragt nach dem Startpunkt"},{"speaker":"Markus","text_de":"Ich arbeite hier, seit ich die Ausbildung beendet habe.","text_en":"I''ve been working here since I finished my training.","grammar_note":"seit + Verb am Ende: beendet habe"},{"speaker":"Anna","text_de":"Was mache ich, bevor ich den Computer anschalte?","text_en":"What do I do before I turn on the computer?","grammar_note":"bevor + Verb am Ende: anschalte"},{"speaker":"Markus","text_de":"Bevor du etwas anschaltest, hol dir am besten deinen Ausweis.","text_en":"Before you turn anything on, best get your ID badge first.","grammar_note":"Nebensatz zuerst: Komma, dann das Verb hol"},{"speaker":"Anna","text_de":"Und was mache ich, nachdem ich mich angemeldet habe?","text_en":"And what do I do after I''ve logged in?","grammar_note":"nachdem + Perfekt am Ende: angemeldet habe"},{"speaker":"Markus","text_de":"Nachdem du dich angemeldet hast, gehst du direkt zu Julia.","text_en":"After you''ve logged in, you go straight to Julia.","grammar_note":"Nebensatz zuerst, Verb im Hauptsatz direkt danach: gehst"},{"speaker":"Anna","text_de":"Als ich das erste Mal hier war, kannte ich niemanden.","text_en":"When I was here for the first time, I knew no one.","grammar_note":"als + Verb am Ende: war (einmaliges Ereignis)"},{"speaker":"Markus","text_de":"Das ändert sich schnell. Während du hier arbeitest, lernst du jeden Tag neue Kollegen kennen.","text_en":"That changes fast. While you work here, you meet new colleagues every day.","grammar_note":"während + Verb am Ende: arbeitest"}],"context_de":"Anna beginnt heute ihren neuen Job. Markus, ihr Kollege, erklärt ihr den ersten Tag.","context_en":"Anna starts her new job today. Markus, her colleague, explains her first day.","grammar_focus_en":"Every line uses a different temporal connector — seit, bevor, nachdem, als, während — always with the verb at the end of its clause, exactly what telc B1 Sprechen Teil 1-2 expects when you describe a sequence of steps."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'afc414bf-b17e-5b66-8164-b0a2118be1db'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '3192bd98-fed1-5212-a18e-41b6b4c00f02'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'common_mistakes', 'Common Mistakes with Temporal Clauses', 'Häufige Fehler bei temporalen Nebensätzen', '{"content_de":"Diese Fehler kommen oft vor. Lies die Beispiele langsam und vergleiche sie.","content_en":"These come up again and again. Read the pairs slowly and compare them."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Wenn ich in Hamburg ankam, war es schon dunkel.","correct":"Als ich in Hamburg ankam, war es schon dunkel.","explanation_de":"Ein einmaliges Ereignis in der Vergangenheit braucht als, nicht wenn.","explanation_en":"A single past event needs als, not wenn."},{"wrong":"Nachdem ich habe die Prüfung bestanden, feiere ich.","correct":"Nachdem ich die Prüfung bestanden habe, feiere ich.","explanation_de":"Im nachdem-Satz steht das Verb ganz am Ende, nicht direkt nach dem Subjekt.","explanation_en":"In a nachdem-clause the verb goes all the way to the end, not right after the subject."},{"wrong":"Nachdem er gegessen hat, ging er schlafen.","correct":"Nachdem er gegessen hatte, ging er schlafen.","explanation_de":"Bei einem Hauptsatz im Präteritum braucht der nachdem-Satz das Plusquamperfekt, nicht das Perfekt.","explanation_en":"With a Präteritum main clause, the nachdem-clause needs the Plusquamperfekt, not the Perfekt."},{"wrong":"Bevor ich unterschreibe den Vertrag, lese ich ihn.","correct":"Bevor ich den Vertrag unterschreibe, lese ich ihn.","explanation_de":"Das Objekt steht vor dem Verb, das Verb bleibt ganz am Ende des bevor-Satzes.","explanation_en":"The object comes before the verb; the verb still stays at the very end of the bevor-clause."},{"wrong":"Ich warte hier bis der Bus kommt.","correct":"Ich warte hier, bis der Bus kommt.","explanation_de":"Vor jedem Nebensatz steht ein Komma, auch vor bis.","explanation_en":"A comma always comes before a subordinate clause, including one with bis."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '3192bd98-fed1-5212-a18e-41b6b4c00f02'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e5256be2-8332-527b-b9de-2b62ed4d11b5'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["als = ein einmaliges Ereignis in der Vergangenheit: Als ich zur Prüfung kam, war ich ruhig.","wenn = Gegenwart, Zukunft oder Wiederholung: Wenn ich Zeit habe, komme ich vorbei.","bevor = vorher, nachdem = danach — beide schicken das Verb ans Ende.","Im nachdem-Satz steht eine frühere Zeitstufe: Perfekt vor Präsens, Plusquamperfekt vor Präteritum.","Plusquamperfekt = hatte/war + Partizip II, nur im nachdem-Satz.","während = gleichzeitig: Während ich koche, höre ich Musik.","bis = bis zu einem Endpunkt: Ich warte, bis der Zug kommt.","seit/seitdem = Start in der Vergangenheit mit Wirkung bis heute: Seit ich hier bin, lerne ich Deutsch.","sobald funktioniert wie wenn — auf diesem Niveau nur zum Verstehen.","Immer ein Komma vor dem Nebensatz, egal wo er steht.","Steht der Nebensatz zuerst, folgt sofort das Verb: Nebensatz, Verb, Subjekt.","Prüfung: Sprechen Teil 1-2, Schreiben (Ablauf), Hören Teil 2 (Reihenfolge)."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e5256be2-8332-527b-b9de-2b62ed4d11b5'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '99d546ba-b46b-50b1-ae7b-a1cd22053583'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'introduction', 'obwohl, damit, sodass, falls: Introduction', 'Einführung: obwohl, damit, sodass, falls', '{"hook_de":"Ich gehe joggen, obwohl es regnet.","hook_en":"Ich gehe joggen, obwohl es regnet. — I go jogging although it''s raining. Four small words let you argue, explain and set conditions.","scenario_en":"Giving your opinion in Sprechen Teil 2, writing a halbformeller Brief, or filling a gap in Sprachbausteine Teil 1.","preview_note_en":"Each connector sends the verb to the end. The trick is choosing the right one for the meaning you want.","preview_highlight":"obwohl, damit, sodass, falls","preview_example_de":"Ich lerne jeden Tag, um die Prüfung zu bestehen, obwohl ich wenig Zeit habe.","preview_example_en":"I study every day to pass the exam, although I have little time.","why_it_matters_en":"telc B1 Sprachbausteine Teil 1 tests exactly these connectors, and the halbformeller Brief in Schreiben and Sprechen Teil 2 both reward reasoned, connected sentences.","german_difference_en":"English often keeps normal word order after although, so that or if; German always pushes the verb to the very end of the Nebensatz.","english_comparison_en":"English: I stay home if it rains. German sends the verb to the end: Ich bleibe zu Hause, falls es regnet."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '99d546ba-b46b-50b1-ae7b-a1cd22053583'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'eab96c08-a6f6-5b78-a423-4e1b93bca22c'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'table', 'Four Connectors at a Glance', 'Vier Konnektoren im Überblick', '{"type":"case_table","headers":["Konnektor","Bedeutung","Beispiel","English"],"rows":[["obwohl","Gegensatz (unerwartetes Ergebnis)","Ich gehe joggen, obwohl es regnet.","concession: I go jogging although it''s raining."],["damit","Zweck für eine andere Person","Sie spricht langsam, damit er sie versteht.","purpose, different subject: she speaks slowly so that he understands her."],["sodass / so ... dass","Folge, Ergebnis","Er übt viel, sodass er die Prüfung besteht.","result: he practices a lot, so he passes the exam."],["falls","Bedingung (wie wenn)","Falls es regnet, bleiben wir zu Hause.","condition: if it rains, we''ll stay home."]],"highlight_row":-1,"description_de":"Alle vier Konnektoren leiten einen Nebensatz ein. Das Verb steht am Ende.","description_en":"All four connectors introduce a Nebensatz, and each one sends the verb to the end."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'damit needs two different subjects; um … zu needs only one.', 'damit hat zwei verschiedene Subjekte, um ... zu hat nur eins.', NULL, NULL, 'The connector you choose depends on the relationship between the two clauses, not on the tense.', 'Der Konnektor hängt von der Beziehung der beiden Sätze ab, nicht von der Zeitform.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'eab96c08-a6f6-5b78-a423-4e1b93bca22c'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'dde53858-6d61-5ad4-91c1-deb1f7bdaa84'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'explanation_core', 'obwohl: Expressing Contrast', 'obwohl: Gegensatz ausdrücken', '{"type":"case_table","headers":["Position","Beispiel","English"],"rows":[["Hauptsatz zuerst","Ich gehe joggen, obwohl es regnet.","I go jogging although it''s raining."],["Nebensatz zuerst","Obwohl es regnet, gehe ich joggen.","Although it''s raining, I go jogging."]],"highlight_row":-1,"description_de":"obwohl leitet einen Nebensatz ein. Das Verb steht am Ende. Bei Nebensatz zuerst folgt direkt nach dem Komma das Verb.","description_en":"obwohl introduces a Nebensatz with the verb at the end. When the Nebensatz comes first, the verb follows immediately after the comma."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'obwohl = although — the second half surprises you.', 'obwohl = etwas spricht dagegen, aber es passiert.', NULL, NULL, 'obwohl connects two facts that don''t normally go together.', 'obwohl verbindet zwei Tatsachen, die eigentlich nicht zusammenpassen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'dde53858-6d61-5ad4-91c1-deb1f7bdaa84'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0b7863b1-3cb4-5e38-a32b-15321fc960f8'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'explanation_comparison', 'damit vs. um … zu: Same or Different Subject?', 'damit vs. um … zu: Gleiches oder anderes Subjekt?', '{"type":"case_table","headers":["Konnektor","Regel","Beispiel"],"rows":[["um ... zu","Gleiches Subjekt in beiden Satzteilen","Ich lerne jeden Tag, um die Prüfung zu bestehen."],["damit","Verschiedene Subjekte","Die Mutter kauft ein Handy, damit ihr Kind sie erreichen kann."]],"highlight_row":-1,"description_de":"Prüfe zuerst das Subjekt: Ist es in beiden Satzteilen gleich, nimm um ... zu. Ist es unterschiedlich, nimm damit.","description_en":"Check the subject first: if it''s the same in both parts, use um … zu; if it differs, use damit."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Same subject? um … zu! Different subject? damit!', 'Gleiches Subjekt? um ... zu! Anderes Subjekt? damit!', NULL, NULL, 'um … zu is impossible with two different subjects — that''s when you need damit.', 'um ... zu geht nicht bei zwei verschiedenen Subjekten. Dann brauchst du damit.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0b7863b1-3cb4-5e38-a32b-15321fc960f8'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '83ad6f60-a4b2-577b-8e7d-40b750685d03'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'explanation_patterns', 'sodass and so … dass: Expressing Result', 'sodass und so … dass: Folge ausdrücken', '{"type":"case_table","headers":["Form","Beispiel","English"],"rows":[["sodass (ein Wort)","Es regnet stark, sodass wir zu Hause bleiben.","It''s raining hard, so we stay home."],["so + Adjektiv ... dass","Es regnet so stark, dass wir zu Hause bleiben.","It''s raining so hard that we stay home."]],"highlight_row":-1,"description_de":"sodass steht direkt nach dem Komma. so ... dass betont ein Adjektiv oder Adverb davor.","description_en":"sodass stands right after the comma. so … dass emphasizes an adjective or adverb before it."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'The sodass-clause always comes after the main clause, never before it.', 'Der sodass-Satz steht immer nach dem Hauptsatz, nie davor.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '83ad6f60-a4b2-577b-8e7d-40b750685d03'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '56973c50-4293-5109-9a8b-62f28c3477e2'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'table', 'falls: Expressing a Condition', 'falls: Eine Bedingung ausdrücken', '{"type":"case_table","headers":["Position","Beispiel","English"],"rows":[["Nebensatz zuerst","Falls es regnet, bleiben wir zu Hause.","If it rains, we''ll stay home."],["Hauptsatz zuerst","Wir bleiben zu Hause, falls es regnet.","We''ll stay home if it rains."]],"highlight_row":-1,"description_de":"falls ist dasselbe wie wenn: eine Bedingung. Es funktioniert genau wie obwohl: Verb am Ende, Komma, Verb direkt nach dem Komma bei Nebensatz zuerst.","description_en":"falls means a condition, like wenn. It behaves exactly like obwohl: verb at the end, a comma, and the verb right after the comma when the Nebensatz comes first."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'falls = it might happen — just like wenn, but with more uncertainty.', 'falls = vielleicht passiert es. Genau wie wenn, aber unsicherer.', NULL, NULL, 'falls is a condition, not a question — never confuse it with ob.', 'falls ist eine Bedingung, keine Frage. Verwechsle es nicht mit ob.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '56973c50-4293-5109-9a8b-62f28c3477e2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '08129c67-25dd-5c49-b611-7b02e7070f10'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'dialogue', 'Dialogue: Job Interview', 'Dialog: Im Bewerbungsgespräch', '{"speakers":["Frau Berger","Herr Aydin"],"exchanges":[{"speaker":"Frau Berger","text_de":"Herr Aydin, Sie möchten also die Abteilung wechseln, obwohl Sie hier gute Ergebnisse haben?","text_en":"Herr Aydin, so you''d like to switch departments although you have good results here?","grammar_note":"obwohl + Verb am Ende: haben"},{"speaker":"Herr Aydin","text_de":"Ja, ich möchte mehr Verantwortung übernehmen, damit mein Team schneller entscheiden kann.","text_en":"Yes, I''d like to take on more responsibility, so that my team can decide faster.","grammar_note":"damit + Modalverb am Ende: kann"},{"speaker":"Frau Berger","text_de":"Verstehe. Falls ein Kollege die Stelle bekommt, suchen wir ab nächstem Monat eine neue Person.","text_en":"I see. If a colleague gets the position, we''ll be looking for a new person from next month.","grammar_note":"falls, Nebensatz zuerst: Verb suchen direkt nach dem Komma"},{"speaker":"Herr Aydin","text_de":"Das passt gut, denn mein aktuelles Projekt ist bald fertig, sodass ich flexibel bin.","text_en":"That fits well, because my current project is almost finished, so I''m flexible.","grammar_note":"sodass + Verb am Ende: bin"},{"speaker":"Frau Berger","text_de":"Gut. Falls Sie Interesse haben, schicken Sie mir bitte Ihre Bewerbung bis Freitag.","text_en":"Good. If you''re interested, please send me your application by Friday.","grammar_note":"falls, Nebensatz zuerst: Verb haben am Ende"},{"speaker":"Herr Aydin","text_de":"Mache ich gern. Obwohl ich nervös bin, freue ich mich sehr auf das Gespräch.","text_en":"I''ll gladly do that. Although I''m nervous, I''m really looking forward to the interview.","grammar_note":"obwohl, Nebensatz zuerst: Verb freue direkt nach dem Komma"},{"speaker":"Frau Berger","text_de":"Das ist normal. Das Gespräch ist so locker, dass Sie schnell entspannt sind.","text_en":"That''s normal. The interview is so relaxed that you''ll quickly feel at ease.","grammar_note":"so + Adjektiv ... dass + Verb am Ende: sind"},{"speaker":"Herr Aydin","text_de":"Vielen Dank, das beruhigt mich sehr.","text_en":"Thank you very much, that reassures me a lot.","grammar_note":"kein Nebensatz hier — kurze Antwort zum Vergleich"}],"context_de":"Herr Aydin möchte in eine andere Abteilung wechseln und spricht mit seiner Chefin Frau Berger.","context_en":"Herr Aydin would like to switch to a different department and talks to his boss, Frau Berger.","grammar_focus_en":"Every connector from this topic appears here in a realistic Bewerbungsgespräch — exactly the register Sprechen Teil 2 and the halbformeller Brief expect."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'A job interview naturally mixes concession (obwohl), purpose (damit) and condition (falls) in a few short turns.', 'Ein Bewerbungsgespräch mischt Gegensatz (obwohl), Zweck (damit) und Bedingung (falls) auf engem Raum.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '08129c67-25dd-5c49-b611-7b02e7070f10'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1a067dae-46f7-5c55-bbde-8621e115f402'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'common_mistakes', 'Five Mistakes to Avoid', 'Fünf Fehler im Überblick', '{"content_de":"Diese Fehler kommen oft vor. Lies die Beispiele langsam.","content_en":"These come up again and again. Read the pairs slowly and compare them."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Obwohl es regnet, ich gehe joggen.","correct":"Obwohl es regnet, gehe ich joggen.","explanation_de":"Nach dem Nebensatz mit obwohl steht das Verb sofort nach dem Komma, dann erst das Subjekt.","explanation_en":"After an obwohl-clause the verb comes right after the comma, then the subject."},{"wrong":"Die Mutter kauft ein Handy, um ihr Kind sie erreichen zu können.","correct":"Die Mutter kauft ein Handy, damit ihr Kind sie erreichen kann.","explanation_de":"Hier sind die Subjekte verschieden: die Mutter und ihr Kind. Deshalb damit.","explanation_en":"um … zu only works when the subject of both parts is the same. Here it''s the mother and her child, so damit is needed."},{"wrong":"Es regnet stark sodass wir zu Hause bleiben.","correct":"Es regnet stark, sodass wir zu Hause bleiben.","explanation_de":"Vor sodass steht immer ein Komma, genau wie vor jedem anderen Nebensatz.","explanation_en":"A comma always comes before sodass, exactly like before any other Nebensatz."},{"wrong":"Ob es regnet, bleiben wir zu Hause.","correct":"Falls es regnet, bleiben wir zu Hause.","explanation_de":"ob leitet eine indirekte Frage ein. Für eine Bedingung brauchst du falls.","explanation_en":"ob introduces an indirect question. For a condition you need falls."},{"wrong":"Sodass ich den Bus verpasst habe, bin ich zu spät aufgestanden.","correct":"Ich bin zu spät aufgestanden, sodass ich den Bus verpasst habe.","explanation_de":"Der sodass-Satz nennt die Folge. Er steht deshalb nach der Ursache, nicht davor.","explanation_en":"The sodass-clause states the result, so it comes after the cause, never before it."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1a067dae-46f7-5c55-bbde-8621e115f402'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '19f9b853-eaf0-5cc0-9914-55b9bd5597f1'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["obwohl = Gegensatz: Ich gehe joggen, obwohl es regnet.","damit = Zweck, anderes Subjekt: Sie spricht langsam, damit er sie versteht.","um ... zu = Zweck, gleiches Subjekt: Ich lerne, um die Prüfung zu bestehen.","sodass / so ... dass = Folge: Es regnet stark, sodass wir zu Hause bleiben.","falls = Bedingung, wie wenn: Falls es regnet, bleiben wir zu Hause.","Das Verb steht immer am Ende des Nebensatzes.","Nebensatz zuerst: Verb direkt nach dem Komma, dann das Subjekt.","Vor jedem Nebensatz steht ein Komma.","Der sodass-Satz steht immer nach dem Hauptsatz, nie davor.","ob ist keine Bedingung. Dafür brauchst du falls.","Prüfung: Sprachbausteine Teil 1, Schreiben (Brief), Sprechen Teil 2."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '19f9b853-eaf0-5cc0-9914-55b9bd5597f1'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'a548afef-fa86-5efa-af88-6dafbd183298'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'introduction', 'Connectors with Inversion: Introduction', 'Einführung: Konnektoren mit Inversion', '{"hook_de":"Es regnet. Deshalb bleibe ich zu Hause. Der Konnektor beginnt, das Verb folgt sofort.","hook_en":"Es regnet. Deshalb bleibe ich zu Hause. — ''It''s raining. That''s why I''m staying home.'' The connector opens the sentence, and the verb follows right away.","scenario_en":"Explaining a decision at work, giving reasons in a semi-formal letter, or making suggestions in a conversation.","preview_note_en":"These connectors open a normal main clause: the verb always stays in position 2, exactly like in any other sentence.","preview_highlight":"deshalb, deswegen, darum, trotzdem, außerdem, sonst, dann, danach, dabei, dagegen","preview_example_de":"Ich bin müde. Trotzdem gehe ich noch joggen.","preview_example_en":"I''m tired. Nevertheless, I''m still going jogging.","why_it_matters_en":"telc B1 rewards these connectors in Sprachbausteine Teil 1, in the halbformeller Brief (Schreiben) and when you give reasons in Sprechen Teil 2–3.","german_difference_en":"English connectors like ''therefore'' or ''nevertheless'' don''t change word order. German ones send the verb to position 2 — but position 2, not position 1.","english_comparison_en":"English: It''s raining, so I''m staying home (normal order after ''so''). German: Es regnet, deshalb bleibe ich zu Hause — bleibe jumps in front of ich."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'These words behave like normal sentence elements — not like weil or obwohl.', 'Diese Wörter verhalten sich wie normale Satzglieder, nicht wie weil oder obwohl.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'a548afef-fa86-5efa-af88-6dafbd183298'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e843022a-cd80-5e53-8a54-344ba2ab6795'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'table', 'The Connectors at a Glance', 'Die Konnektoren im Überblick', '{"type":"case_table","headers":["Konnektor","Bedeutung","Beispiel"],"rows":[["deshalb / deswegen / darum","Grund → Folge (therefore)","Ich bin krank. Deshalb bleibe ich im Bett."],["trotzdem","Gegensatz (nevertheless)","Es regnet. Trotzdem gehen wir spazieren."],["außerdem","weiteres Argument (besides)","Die Miete ist hoch. Außerdem ist die Wohnung laut."],["sonst","negative Folge (otherwise)","Lern jetzt, sonst bestehst du die Prüfung nicht."],["dann","zeitliche Folge (then)","Wir essen. Dann räumen wir die Küche auf."],["danach","nächster Schritt (after that)","Wir duschen. Danach ziehen wir uns an."],["dabei","gleichzeitig, oft mitten im Satz (thereby)","Sie kocht und hört dabei Radio."],["dagegen","Gegensatz zwischen zwei Dingen (in contrast)","Er mag Fußball. Sie dagegen mag Tennis."]],"highlight_row":-1,"description_de":"Alle diese Wörter stehen in einem Hauptsatz. Das Verb bleibt immer auf Position 2.","description_en":"All of these are main-clause connectors: the verb always stays in position 2, wherever the connector itself sits."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'deshalb, deswegen, darum — three words, one meaning: therefore.', 'deshalb, deswegen, darum — drei Wörter, eine Bedeutung: deshalb.', NULL, NULL, 'Choosing the right connector is a meaning question, not a grammar question — the position-2 rule is the same for all ten.', 'Die Wahl des Konnektors ist eine Bedeutungsfrage. Die Regel Verb auf Position 2 gilt für alle zehn gleich.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e843022a-cd80-5e53-8a54-344ba2ab6795'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '497d8a5b-fae2-5196-b1b7-f36452b81d31'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'pattern', 'How to Build the Sentence', 'So baust du den Satz', '{"type":"steps","steps":[{"step":1,"title_de":"Finde den Grund oder die Situation.","title_en":"Find the reason or situation.","detail_de":"Es regnet. → Das ist Satz eins.","detail_en":"Es regnet. → this is the first sentence."},{"step":2,"title_de":"Wähle den passenden Konnektor.","title_en":"Choose the right connector.","detail_de":"Grund → Folge: deshalb. Gegensatz: trotzdem. Weiterer Punkt: außerdem.","detail_en":"Reason → result: deshalb. Contrast: trotzdem. Extra point: außerdem."},{"step":3,"title_de":"Setze den Konnektor auf Position 1.","title_en":"Put the connector in position 1.","detail_de":"Deshalb bleibe ich zu Hause. Das Verb bleibe steht direkt nach dem Konnektor.","detail_en":"Deshalb bleibe ich zu Hause. The verb bleibe comes right after the connector."},{"step":4,"title_de":"Oder: Setze den Konnektor mitten in den Satz.","title_en":"Or: put the connector in the middle of the sentence.","detail_de":"Ich bleibe deshalb zu Hause. Das Verb bleibt auf Position 2, nicht der Konnektor.","detail_en":"Ich bleibe deshalb zu Hause. The verb still holds position 2, not the connector."}],"description_de":"Vier Schritte: Grund finden, Konnektor wählen, Position 1 oder Mitte, Verb bleibt auf Position 2.","description_en":"Four steps: find the reason, pick the connector, choose position 1 or mid-sentence — the verb always stays in position 2."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Whether the connector opens the sentence or sits in the middle, the finite verb never leaves position 2.', 'Ob der Konnektor vorne oder mitten im Satz steht, das Verb bleibt immer auf Position 2.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '497d8a5b-fae2-5196-b1b7-f36452b81d31'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '28853588-c197-5a5a-8d47-43400ed24826'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'explanation_comparison', 'Main-Clause Connector or Subordinator?', 'Hauptsatz-Konnektor oder Nebensatz-Konnektor?', '{"type":"case_table","headers":["Nebensatz (Verb am Ende)","Hauptsatz-Konnektor (Verb Position 2)","English"],"rows":[["Ich bleibe zu Hause, weil es regnet.","Es regnet. Deshalb bleibe ich zu Hause.","because vs. that''s why — same reason, two structures"],["Er geht raus, obwohl es regnet.","Es regnet. Trotzdem geht er raus.","although vs. nevertheless — same contrast, two structures"],["Ich spare, damit ich eine Reise machen kann.","Ich möchte eine Reise machen. Deshalb spare ich.","so that vs. that''s why + purpose sentence, same goal"]],"highlight_row":-1,"description_de":"weil, obwohl und damit schicken das Verb ans Ende. deshalb, trotzdem und die anderen Konnektoren schicken das Verb nur auf Position 2.","description_en":"weil, obwohl and damit send the verb to the very end. deshalb, trotzdem and the other connectors only push the verb to position 2."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'You already know weil, dass, wenn, ob, obwohl and damit from earlier topics — they all send the verb to the end.', 'weil, dass, wenn, ob, obwohl und damit kennst du schon. Sie schicken das Verb ans Ende.', 'Same meaning, different job: a subordinator glues one clause to another; deshalb, trotzdem and co. start their own independent main clause.', 'Gleiche Bedeutung, andere Aufgabe: Ein Nebensatz-Konnektor verbindet zwei Sätze zu einem. deshalb, trotzdem und Co. beginnen einen eigenen, selbstständigen Hauptsatz.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '28853588-c197-5a5a-8d47-43400ed24826'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '229a183e-b6f2-5269-b3b6-81778a48c5bd'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'table', 'Position 1 or Mid-Sentence', 'Position 1 oder mitten im Satz', '{"type":"case_table","headers":["Position 1","Mitten im Satz","English"],"rows":[["Es ist kalt. Trotzdem öffnet sie das Fenster.","Sie öffnet trotzdem das Fenster.","cold outside — she opens the window anyway"],["Der Zug hat Verspätung. Deshalb komme ich später.","Ich komme deshalb später.","the train is late — that''s why I''m coming later"],["Kauf noch Brot. Außerdem brauchen wir Milch.","Wir brauchen außerdem Milch.","buy bread — besides, we also need milk"],["Er ist krank. Dagegen fühlt sie sich fit.","Sie fühlt sich dagegen fit.","he is sick — she, in contrast, feels fit"]],"highlight_row":-1,"description_de":"Der Konnektor kann vorne stehen (Position 1) oder mitten im Satz, direkt nach dem Verb. Das Verb bleibt immer auf Position 2.","description_en":"The connector can open the sentence (position 1) or sit mid-sentence, right after the verb. The verb always stays in position 2."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Moving the connector never moves the verb — the verb owns position 2 no matter what.', 'Wenn der Konnektor seinen Platz wechselt, bleibt das Verb trotzdem auf Position 2.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '229a183e-b6f2-5269-b3b6-81778a48c5bd'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'b78798dd-97eb-5d09-a6ca-2031db97b276'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'tip', 'Where This Scores in the Exam', 'Wo das in der Prüfung zählt', '{"content_de":"Sprachbausteine Teil 1 testet oft genau diese Konnektoren. Im Schreiben (halbformeller Brief) klingst du mit trotzdem und deshalb überzeugend: Trotzdem möchte ich Sie um eine Antwort bitten.","content_en":"Sprachbausteine Teil 1 often tests exactly these connectors. In Schreiben (the halbformeller Brief), trotzdem and deshalb make your argument sound convincing: Trotzdem möchte ich Sie um eine Antwort bitten."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'In a formal letter, opening a sentence with Trotzdem or Deshalb (then the verb) is a strong, natural way to argue your point.', 'In einem formellen Brief klingt ein Satz mit Trotzdem oder Deshalb am Anfang überzeugend und natürlich.', 'Sprechen Teil 2–3 rewards deshalb and trotzdem when you justify an opinion or a suggestion.', 'In Sprechen Teil 2–3 punktest du mit deshalb und trotzdem, wenn du eine Meinung oder einen Vorschlag begründest.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'b78798dd-97eb-5d09-a6ca-2031db97b276'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ee4099e5-34d6-5f8e-b2dc-17e0f22902c5'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'dialogue', 'Dialogue: A Decision About Further Training', 'Dialog: Eine Entscheidung über eine Weiterbildung', '{"speakers":["Frau Celik","Herr Novak"],"exchanges":[{"speaker":"Frau Celik","text_de":"Der Excel-Kurs kostet viel Geld. Trotzdem möchte ich ihn machen.","text_en":"The Excel course costs a lot of money. Nevertheless, I want to take it.","grammar_note":"trotzdem + Verb auf Position 2: möchte steht direkt danach"},{"speaker":"Herr Novak","text_de":"Warum ist dir das so wichtig?","text_en":"Why does it matter so much to you?","grammar_note":"einfache W-Frage zum Vergleich"},{"speaker":"Frau Celik","text_de":"Ich brauche die Kenntnisse für meinen Beruf. Außerdem interessiert mich das Thema.","text_en":"I need the skills for my job. Besides, the topic interests me.","grammar_note":"außerdem + Verb: interessiert auf Position 2"},{"speaker":"Herr Novak","text_de":"Meldest du dich schon diese Woche an?","text_en":"Are you signing up already this week?","grammar_note":"Frage zum Vergleich, kein Konnektor hier"},{"speaker":"Frau Celik","text_de":"Ja, sonst sind alle Plätze weg.","text_en":"Yes, otherwise all the spots will be gone.","grammar_note":"sonst + Verb: sind auf Position 2"},{"speaker":"Herr Novak","text_de":"Gute Idee. Dann melde ich mich vielleicht auch an.","text_en":"Good idea. Then maybe I''ll sign up too.","grammar_note":"dann + Verb: melde auf Position 2"},{"speaker":"Frau Celik","text_de":"Der Kurs beginnt im Januar. Danach gibt es noch einen weiteren Kurs.","text_en":"The course starts in January. After that there''s another course too.","grammar_note":"danach + Verb: gibt auf Position 2"},{"speaker":"Herr Novak","text_de":"Perfekt, das passt gut in meinen Zeitplan.","text_en":"Perfect, that fits well into my schedule.","grammar_note":"kein Konnektor hier — normaler Hauptsatz zum Vergleich"}],"context_de":"Frau Celik und Herr Novak sprechen in der Mittagspause über eine Weiterbildung.","context_en":"Frau Celik and Herr Novak talk about a training course during their lunch break.","grammar_focus_en":"Every reason and contrast here uses a main-clause connector (trotzdem, außerdem, sonst, dann, danach) with the verb staying in position 2 — exactly what Sprechen Teil 2 rewards."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'In Sprechen Teil 2, a natural-sounding reason or contrast with these connectors scores higher than a long, hesitant sentence.', 'In Sprechen Teil 2 punktest du mit einem natürlichen Grund oder Gegensatz mehr als mit einem langen, zögerlichen Satz.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ee4099e5-34d6-5f8e-b2dc-17e0f22902c5'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'c0418762-850e-5855-8f02-b6b4068bab39'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'common_mistakes', 'Five Mistakes to Avoid', 'Fünf Fehler im Überblick', '{"content_de":"Diese Fehler passieren oft, wenn Lernende deshalb wie weil benutzen. Lies die Paare langsam.","content_en":"These mistakes happen often when learners treat deshalb like weil. Read the pairs slowly and compare them."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Es regnet. Deshalb ich bleibe zu Hause.","correct":"Es regnet. Deshalb bleibe ich zu Hause.","explanation_de":"Nach deshalb kommt sofort das Verb, nicht das Subjekt. Position 2 gehört dem Verb.","explanation_en":"The verb comes right after deshalb, not the subject — position 2 belongs to the verb."},{"wrong":"Ich bin müde, trotzdem ich gehe zur Arbeit.","correct":"Ich bin müde, trotzdem gehe ich zur Arbeit.","explanation_de":"trotzdem ist kein Nebensatz-Konnektor wie obwohl. Das Verb steht auf Position 2, nicht am Ende.","explanation_en":"trotzdem is not a subordinator like obwohl. The verb stays in position 2, not at the end."},{"wrong":"Sie hat keine Zeit, deswegen sie kann nicht kommen.","correct":"Sie hat keine Zeit, deswegen kann sie nicht kommen.","explanation_de":"Nach deswegen steht das Verb, dann erst das Subjekt sie.","explanation_en":"After deswegen comes the verb, then the subject sie."},{"wrong":"Beeil dich, sonst du verpasst den Zug.","correct":"Beeil dich, sonst verpasst du den Zug.","explanation_de":"sonst schickt das Verb auch auf Position 2, direkt nach sonst.","explanation_en":"sonst also sends the verb to position 2, right after itself."},{"wrong":"Ich bin krank, weil deshalb bleibe ich zu Hause.","correct":"Ich bin krank. Deshalb bleibe ich zu Hause.","explanation_de":"weil und deshalb stehen nie zusammen in einem Satz. Nimm entweder einen Nebensatz mit weil oder einen Hauptsatz mit deshalb.","explanation_en":"weil and deshalb never appear together. Use either a weil-clause or a separate deshalb-sentence."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'c0418762-850e-5855-8f02-b6b4068bab39'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '031778ef-afba-5f31-b5fc-0560b1f9c578'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["deshalb, deswegen, darum: gleiche Bedeutung, drei Wörter.","trotzdem: Gegensatz, aber Hauptsatz.","außerdem: ein weiteres Argument.","sonst: eine negative Folge.","dann, danach: zeitliche Reihenfolge.","dabei: oft mitten im Satz, gleichzeitige Handlung.","dagegen: Gegensatz zwischen zwei Dingen.","Position 1: Konnektor zuerst, dann sofort das Verb.","Mitten im Satz: Verb zuerst, der Konnektor danach.","weil, obwohl, damit sind Nebensatz-Konnektoren: Verb am Ende.","deshalb, trotzdem und Co. sind Hauptsatz-Konnektoren: Verb auf Position 2.","Prüfung: Sprachbausteine Teil 1, Schreiben (halbformeller Brief), Sprechen Teil 2–3."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '031778ef-afba-5f31-b5fc-0560b1f9c578'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '356238c2-fe90-5a29-bb5c-0fed3586ba41'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'introduction', 'Two-Part Connectors: Introduction', 'Einführung: Zweiteilige Konnektoren', '{"hook_de":"Entweder gehst du zur Arbeit, oder du bleibst zu Hause.","hook_en":"Either you go to work, or you stay home — German builds this with two connected words, not one.","scenario_en":"Comparing two options at work, describing an apartment, or weighing Vor- und Nachteile in a conversation or letter.","preview_note_en":"Five connector pairs, each with its own word-order rule after the first part.","preview_highlight":"entweder … oder, nicht nur … sondern auch, sowohl … als auch, weder … noch, zwar … aber","preview_example_de":"Das Konzert ist zwar teuer, aber es lohnt sich.","preview_example_en":"The concert is admittedly expensive, but it''s worth it.","why_it_matters_en":"telc B1 Sprachbausteine Teil 1 often tests exactly these connector pairs, and Schreiben and Sprechen Teil 2 reward using them to compare options.","german_difference_en":"English pairs like either...or don''t move the verb; German entweder can push the verb right after it.","english_comparison_en":"English: Either we go to the cinema, or we stay home. German: Entweder gehen wir ins Kino, oder wir bleiben zu Hause — the verb moves right after entweder."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '356238c2-fe90-5a29-bb5c-0fed3586ba41'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '7f5c4cb0-ce64-5d94-9146-00bba3a0872c'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'table', 'The Five Connector Pairs', 'Die fünf Konnektorenpaare', '{"type":"case_table","headers":["Konnektor","Bedeutung","Beispiel"],"rows":[["entweder … oder","eine von zwei Möglichkeiten","Wir fahren entweder mit dem Zug oder mit dem Bus."],["nicht nur … sondern auch","eine zusätzliche Information","Er ist nicht nur pünktlich, sondern auch freundlich."],["sowohl … als auch","beides zusammen, ohne Ausnahme","Sowohl die Küche als auch das Bad sind neu."],["weder … noch","doppelte Verneinung","Ich trinke weder Kaffee noch Tee."],["zwar … aber","ein Zugeständnis mit Gegensatz","Das Auto ist zwar praktisch, aber es verschmutzt die Umwelt."]],"highlight_row":-1,"description_de":"Jedes Paar verbindet zwei Wörter, Satzteile oder ganze Hauptsätze.","description_en":"Each pair connects two words, phrases, or whole main clauses."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'sowohl … als auch and sowohl … wie auch are both correct — als and wie can both partner with sowohl.', 'sowohl … als auch = sowohl … wie auch. Beide Formen sind korrekt.', NULL, NULL, 'Every pair is fixed: never mix the two halves of different pairs.', 'Jedes Paar ist fest: Mische nie die Hälften von zwei verschiedenen Paaren.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '7f5c4cb0-ce64-5d94-9146-00bba3a0872c'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '2c4ce5ab-4878-51ef-9246-ad76c054d329'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'pattern', 'How to Join Two Words or Phrases', 'So verbindest du zwei Wörter oder Satzteile', '{"type":"steps","steps":[{"step":1,"title_de":"Finde die zwei Elemente.","title_en":"Find the two elements.","detail_de":"Zwei Nomen, Adjektive oder Verben, die zusammengehören.","detail_en":"Two nouns, adjectives, or verbs that belong together."},{"step":2,"title_de":"Setze den ersten Konnektor direkt davor.","title_en":"Place the first connector directly before it.","detail_de":"sowohl Tee, weder Kaffee, nicht nur Deutsch.","detail_en":"sowohl Tee, weder Kaffee, nicht nur Deutsch — the first half goes directly before the first element."},{"step":3,"title_de":"Setze den zweiten Konnektor direkt vor das zweite Element.","title_en":"Place the second connector directly before the second element.","detail_de":"als auch Kaffee, noch Tee, sondern auch Englisch.","detail_en":"als auch Kaffee, noch Tee, sondern auch Englisch — the second half goes directly before the second element."},{"step":4,"title_de":"Die Wortstellung im Satz bleibt normal.","title_en":"The sentence''s word order stays normal.","detail_de":"Er mag sowohl Fußball als auch Tennis. Subjekt steht vor dem Verb.","detail_en":"Er mag sowohl Fußball als auch Tennis. The subject stays before the verb."}],"description_de":"Diese vier Schritte funktionieren für alle fünf Konnektorenpaare.","description_en":"These four steps work for all five connector pairs."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '2c4ce5ab-4878-51ef-9246-ad76c054d329'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '502b17af-37c5-5901-b8cf-f655037b9773'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'table', 'Word Order: Joining Two Full Clauses', 'Wortstellung: Zwei ganze Hauptsätze verbinden', '{"type":"case_table","headers":["Erster Teil","Zweiter Teil","Beispiel"],"rows":[["entweder: Verb meist direkt danach (Inversion optional)","oder: normale Wortstellung","Entweder bleibst du hier, oder du kommst mit."],["zwar: Verb direkt danach","aber: normale Wortstellung","Zwar regnet es, aber wir gehen spazieren."]],"highlight_row":-1,"description_de":"Steht der erste Teil ganz am Satzanfang, folgt das Verb meist sofort danach. Bei entweder ist die Reihenfolge ohne Inversion ebenfalls korrekt.","description_en":"When the first part opens the sentence, the verb usually follows immediately. With entweder the non-inverted order is equally correct."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'oder, aber, and sondern never change the word order in the second part.', 'oder, aber und sondern verändern die Wortstellung im zweiten Teil nicht.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '502b17af-37c5-5901-b8cf-f655037b9773'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '21226de9-0e65-5863-85ed-e759773947c3'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'explanation_comparison', 'Which Connectors Trigger Inversion?', 'Welche Konnektoren lösen Inversion aus?', '{"type":"case_table","headers":["Erster Teil","Verhalten im Hauptsatz","Regel"],"rows":[["entweder","kann wie ein Adverb auf Position eins stehen","Verb direkt danach ist üblich. Ohne Inversion ist es auch korrekt."],["zwar, nicht nur","wie ein Adverb auf Position eins","Das Verb steht direkt nach dem ersten Teil."],["sowohl, weder","verbinden in diesem Kapitel nur Wörter, keine ganzen Sätze","Die normale Wortstellung bleibt erhalten."],["oder, aber, sondern","reine Konjunktionen","Sie zählen nicht als Satzglied und verändern die Wortstellung nicht."]],"highlight_row":-1,"description_de":"In diesem Kapitel schieben nur entweder, zwar und nicht nur das Verb vor das Subjekt. Bei entweder ist diese Inversion optional.","description_en":"In this chapter, only entweder, zwar, and nicht nur push the verb before the subject. With entweder this inversion is optional."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '21226de9-0e65-5863-85ed-e759773947c3'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9e61e349-5262-5573-beb6-746a8bd484bd'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'tip', 'Where This Scores in the telc B1 Exam', 'Wo das in der telc-B1-Prüfung zählt', '{"content_de":"In Sprachbausteine Teil 1 wählst du oft genau diese Konnektoren. Beim Sprechen (Vor- und Nachteile) und beim Schreiben von Vorschlägen hilft dir diese Struktur.","content_en":"In Sprachbausteine Teil 1 you often choose exactly these connectors. They also help in Sprechen (weighing Vor- und Nachteile) and in Schreiben when you make suggestions."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'In a half-formal letter, zwar … aber fits especially well with suggestions and compromises.', 'Im halbformellen Brief passt zwar … aber besonders gut zu Vorschlägen und Kompromissen.', 'Practice each pair with your own example from everyday life.', 'Übe jedes Paar mit einem eigenen Beispiel aus deinem Alltag.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '9e61e349-5262-5573-beb6-746a8bd484bd'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '07318223-1484-5b9d-9cd5-4067ce9caeea'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'dialogue', 'Dialogue: Wohnungsbesichtigung', 'Dialog: Wohnungsbesichtigung', '{"speakers":["Herr Yilmaz","Frau Krüger"],"exchanges":[{"speaker":"Herr Yilmaz","text_de":"Die Wohnung ist zwar klein, aber sie ist zentral und ruhig.","text_en":"The apartment is admittedly small, but it''s central and quiet.","grammar_note":"zwar nach dem Verb ist, aber = normale Wortstellung"},{"speaker":"Frau Krüger","text_de":"Das stimmt. Sowohl die Lage als auch der Preis passen gut.","text_en":"True. Both the location and the price work well.","grammar_note":"sowohl … als auch bildet das Subjekt"},{"speaker":"Herr Yilmaz","text_de":"Entweder unterschreiben wir heute, oder wir warten eine weitere Woche.","text_en":"Either we sign today, or we wait another week.","grammar_note":"entweder am Anfang: Verb direkt danach"},{"speaker":"Frau Krüger","text_de":"Ich möchte nicht warten. Weder der Lärm noch der Weg zur Arbeit stört mich.","text_en":"I don''t want to wait. Neither the noise nor the commute bothers me.","grammar_note":"weder … noch verneint das Subjekt"},{"speaker":"Herr Yilmaz","text_de":"Gut, dann brauchen wir nicht nur die Unterschrift, sondern auch die Kaution.","text_en":"Good, then we need not only the signature, but also the deposit.","grammar_note":"nicht nur … sondern auch verbindet zwei Objekte"},{"speaker":"Frau Krüger","text_de":"Ich rufe morgen den Vermieter an.","text_en":"I''ll call the landlord tomorrow.","grammar_note":"kein Konnektor hier — normaler Hauptsatz zum Vergleich"},{"speaker":"Herr Yilmaz","text_de":"Perfekt, dann ist alles klar.","text_en":"Perfect, then everything is settled.","grammar_note":"kein Konnektor hier — kurzer Abschluss"}],"context_de":"Herr Yilmaz und Frau Krüger besichtigen zusammen eine Wohnung.","context_en":"Herr Yilmaz and Frau Krüger view an apartment together.","grammar_focus_en":"All five two-part connector pairs appear here in a realistic Wohnungssuche conversation."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '07318223-1484-5b9d-9cd5-4067ce9caeea'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '7861703c-582d-534a-a029-2bbd4b5f0b30'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'common_mistakes', 'Common Mistakes with Two-Part Connectors', 'Häufige Fehler bei zweiteiligen Konnektoren', '{"content_de":"Diese Fehler kommen oft vor. Lies die Beispiele langsam.","content_en":"These mistakes come up often. Read the examples slowly."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Er ist nicht nur pünktlich, sondern freundlich.","correct":"Er ist nicht nur pünktlich, sondern auch freundlich.","explanation_de":"Bei zwei gleichwertigen Informationen darf auch nach sondern nicht fehlen.","explanation_en":"When both pieces of information are equally weighted, auch may not be dropped after sondern."},{"wrong":"Sowohl mein Bruder und meine Schwester kommen.","correct":"Sowohl mein Bruder als auch meine Schwester kommen.","explanation_de":"sowohl passt nicht zu „und“. Der feste Partner ist „als auch“ (oder „wie auch“).","explanation_en":"sowohl does not pair with und; its fixed partner is als auch (or wie auch)."},{"wrong":"Ich trinke weder Kaffee oder Tee.","correct":"Ich trinke weder Kaffee noch Tee.","explanation_de":"Nach weder folgt immer „noch“, nie „oder“.","explanation_en":"noch always follows weder, never oder."},{"wrong":"Zwar ist der Kurs lang aber er ist nützlich.","correct":"Zwar ist der Kurs lang, aber er ist nützlich.","explanation_de":"Vor aber steht immer ein Komma, wenn aber zwei Hauptsätze verbindet.","explanation_en":"A comma always precedes aber when it connects two main clauses."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '7861703c-582d-534a-a029-2bbd4b5f0b30'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1596bd0d-7e19-5cfa-8608-856f1725cf4b'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["entweder … oder = eine von zwei Möglichkeiten.","Nach entweder am Satzanfang steht meist das Verb; die Reihenfolge ohne Inversion ist auch korrekt.","oder verändert die Wortstellung nicht.","nicht nur … sondern auch = eine zusätzliche Information; bei zwei gleichwertigen Informationen auch nie weglassen.","sowohl … als auch = beides zusammen; als auch bleibt immer zusammen.","weder … noch = doppelte Verneinung; nach weder nie oder.","zwar … aber = Zugeständnis und Gegensatz; Komma vor aber.","Nach zwar am Satzanfang: Verb direkt danach.","Prüfung: Sprachbausteine Teil 1, Sprechen Teil 2, Schreiben."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1596bd0d-7e19-5cfa-8608-856f1725cf4b'::uuid);

-- Examples
INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ce28caf9-3dd2-52fd-aa49-8308907521b9'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Als ich zum ersten Interview kam, war ich sehr nervös.', 'When I came to my first interview, I was very nervous.', 'Als ich zum ersten Interview kam', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'als introduces a single past event.', 'als beschreibt ein einmaliges Ereignis in der Vergangenheit.', '{"Als":"when (single past event)","ich":"I","zum ersten Interview":"to the first interview","kam":"came (kommen, Präteritum, ich)","war ich":"I was (sein, Präteritum)","sehr nervös":"very nervous"}'::jsonb, 2, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ce28caf9-3dd2-52fd-aa49-8308907521b9'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'd07a49e2-7da6-5235-b5e6-190e1ad34b0d'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Wenn ich Stress habe, gehe ich abends spazieren.', 'When(ever) I''m stressed, I go for a walk in the evening.', 'Wenn ich Stress habe', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'wenn describes a present habit here, not a one-time action.', 'wenn beschreibt hier eine Gewohnheit in der Gegenwart, keine einmalige Handlung.', '{"Wenn":"when(ever), if","ich":"I","Stress habe":"am stressed (haben, Präsens)","gehe ich":"I go (gehen, Präsens)","abends":"in the evening","spazieren":"for a walk"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'd07a49e2-7da6-5235-b5e6-190e1ad34b0d'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ea20a095-9ef3-5abe-9a94-514c84ff1130'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Wenn wir genug Geld sparen, heiraten wir.', 'When we save enough money, we''ll get married.', 'Wenn wir genug Geld sparen', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'wenn refers to the future here: the saving comes before the wedding.', 'wenn steht hier für die Zukunft: Das Sparen kommt vor der Hochzeit.', '{"Wenn":"when, if","wir":"we","genug Geld sparen":"save enough money (Präsens with future meaning)","heiraten wir":"we get married (heiraten, Präsens)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ea20a095-9ef3-5abe-9a94-514c84ff1130'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '286c9f0e-f691-5839-a4a7-189cfb98fdee'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Bevor ich den Mietvertrag unterschreibe, lese ich ihn genau durch.', 'Before I sign the rental contract, I read it carefully.', 'Bevor ich den Mietvertrag unterschreibe', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'bevor shows that the reading happens before the signing. Both verbs are in the present tense.', 'bevor zeigt: Das Lesen passiert vor dem Unterschreiben. Beide Verben stehen im Präsens.', '{"Bevor":"before","ich":"I","den Mietvertrag":"the rental contract","unterschreibe":"sign (unterschreiben, Präsens, ich)","lese ich":"I read (lesen, Präsens)","ihn genau durch":"it carefully (durchlesen, separable)"}'::jsonb, 2, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '286c9f0e-f691-5839-a4a7-189cfb98fdee'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ecd9a4f8-e70b-51d9-90ab-2120ba35cef3'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Nachdem sie die Kündigung bekommen hatte, ging sie zum Arbeitsamt.', 'After she had received the notice of termination, she went to the job centre.', 'Nachdem sie die Kündigung bekommen hatte', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'The main clause is in the Präteritum, so the nachdem-clause needs the Plusquamperfekt.', 'Der Hauptsatz steht im Präteritum, deshalb steht im nachdem-Satz das Plusquamperfekt.', '{"Nachdem":"after","sie":"she","die Kündigung":"the notice of termination","bekommen hatte":"had received (Plusquamperfekt)","ging sie":"she went (gehen, Präteritum)","zum Arbeitsamt":"to the job centre"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ecd9a4f8-e70b-51d9-90ab-2120ba35cef3'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '275f0244-c760-5a96-822d-823a910e5249'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Nachdem ich die Prüfung bestanden habe, melde ich mich für den nächsten Kurs an.', 'After I''ve passed the exam, I register for the next course.', 'Nachdem ich die Prüfung bestanden habe', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'The main clause is in the present, so the nachdem-clause needs the Perfekt, not the Plusquamperfekt.', 'Der Hauptsatz steht im Präsens, deshalb steht im nachdem-Satz das Perfekt, nicht das Plusquamperfekt.', '{"Nachdem":"after","ich":"I","die Prüfung":"the exam","bestanden habe":"have passed (Perfekt)","melde ich mich":"I register (anmelden, Präsens, reflexiv)","für den nächsten Kurs":"for the next course","an":"(separable particle)"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '275f0244-c760-5a96-822d-823a910e5249'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '7e6bb5b8-85fb-5e42-9b0f-7c924f914b1f'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Während ich beim Arzt warte, lese ich eine Zeitschrift.', 'While I wait at the doctor''s, I read a magazine.', 'Während ich beim Arzt warte', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'während shows two actions happening at the same time — both in the present tense.', 'während zeigt zwei Handlungen zur gleichen Zeit — beide im Präsens.', '{"Während":"while","ich":"I","beim Arzt":"at the doctor''s","warte":"wait (warten, Präsens, ich)","lese ich":"I read (lesen, Präsens)","eine Zeitschrift":"a magazine"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '7e6bb5b8-85fb-5e42-9b0f-7c924f914b1f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '73cf9a75-d11a-5ce0-ad4d-03b0f9e1c38d'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Ich bleibe hier, bis der Techniker kommt.', 'I''ll stay here until the technician comes.', 'bis der Techniker kommt', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'Here the main clause comes first, followed by a comma and the bis-clause.', 'Hier steht der Hauptsatz zuerst, danach folgt der bis-Satz mit Komma.', '{"Ich":"I","bleibe":"stay (bleiben, Präsens, ich)","hier":"here","bis":"until","der Techniker":"the technician","kommt":"comes (kommen, Präsens, er)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '73cf9a75-d11a-5ce0-ad4d-03b0f9e1c38d'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '42c9babe-d39a-5a33-bed5-15c146fbaf81'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Seit ich in diesem Haus wohne, kenne ich alle Nachbarn.', 'Since I''ve lived in this house, I''ve known all the neighbours.', 'Seit ich in diesem Haus wohne', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'seit marks the start in the past; its effect continues into the present.', 'seit markiert den Start in der Vergangenheit; die Wirkung dauert bis heute an.', '{"Seit":"since","ich":"I","in diesem Haus":"in this house","wohne":"live (wohnen, Präsens, ich)","kenne ich":"I know (kennen, Präsens)","alle Nachbarn":"all the neighbours"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '42c9babe-d39a-5a33-bed5-15c146fbaf81'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '10a0678e-85d5-53d9-9f00-81c5818455dd'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 'Ich war sehr überrascht, als ich das Ergebnis sah.', 'I was very surprised when I saw the result.', 'als ich das Ergebnis sah', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'The main clause comes first; the als-clause with the single event follows.', 'Der Hauptsatz steht zuerst; der als-Satz mit dem einmaligen Ereignis folgt danach.', '{"Ich":"I","war":"was (sein, Präteritum, ich)","sehr überrascht":"very surprised","als":"when","ich":"I","das Ergebnis":"the result","sah":"saw (sehen, Präteritum, ich)"}'::jsonb, 2, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '10a0678e-85d5-53d9-9f00-81c5818455dd'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5ad19da4-63e4-5411-b355-6cc305100546'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Ich gehe joggen, obwohl es regnet.', 'I go jogging although it''s raining.', 'obwohl es regnet', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'obwohl introduces the contrast; the verb regnet closes the clause.', 'obwohl leitet den Gegensatz ein. Das Verb regnet steht am Ende.', '{"Ich":"I","gehe":"go (gehen, Präsens, ich)","joggen":"jogging (Infinitiv als Aktivität)","obwohl":"although","es":"it","regnet":"rains (regnen, Präsens, es)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5ad19da4-63e4-5411-b355-6cc305100546'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4fc543c4-2fd7-555d-9e87-f7ab1a06c8a0'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Obwohl Peter müde ist, arbeitet er noch zwei Stunden.', 'Although Peter is tired, he still works for two hours.', 'Obwohl Peter müde ist', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The Nebensatz comes first, so the verb arbeitet follows directly after the comma.', 'Der Nebensatz steht zuerst, deshalb folgt das Verb arbeitet direkt nach dem Komma.', '{"Obwohl":"although","Peter":"Peter (name)","müde":"tired","ist":"is (sein, Präsens, er)","arbeitet":"works (arbeiten, Präsens, er)","er":"he","noch":"still","zwei":"two","Stunden":"hours"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4fc543c4-2fd7-555d-9e87-f7ab1a06c8a0'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '42e3e2a9-4a90-5cde-a7e8-38ec43966ef0'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Ich spare jeden Monat Geld, um eine Reise zu machen.', 'I save money every month in order to take a trip.', 'um eine Reise zu machen', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Same subject in both parts (I save, I travel), so um … zu is used instead of damit.', 'Gleiches Subjekt in beiden Teilen (ich spare, ich reise), deshalb um ... zu statt damit.', '{"Ich":"I","spare":"save (sparen, Präsens, ich)","jeden":"every (Akkusativ, masculine)","Monat":"month","Geld":"money","um":"in order (um ... zu)","eine":"a (feminine, Akkusativ)","Reise":"trip","zu":"to (zu + Infinitiv)","machen":"to make, to do (infinitive)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '42e3e2a9-4a90-5cde-a7e8-38ec43966ef0'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '81664ea6-4539-5f41-b6d4-ecdbd19eed77'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Die Lehrerin spricht langsam, damit die Schüler sie verstehen.', 'The teacher speaks slowly so that the students understand her.', 'damit die Schüler sie verstehen', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'Two different subjects (die Lehrerin / die Schüler), so damit is correct, not um … zu.', 'Zwei verschiedene Subjekte (die Lehrerin / die Schüler), deshalb damit und nicht um ... zu.', '{"Die":"the (feminine)","Lehrerin":"teacher (female)","spricht":"speaks (sprechen, Präsens, sie)","langsam":"slowly","damit":"so that","die":"the (plural)","Schüler":"students, pupils","sie":"they","verstehen":"understand (verstehen, Präsens, sie/plural)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '81664ea6-4539-5f41-b6d4-ecdbd19eed77'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'd3534758-0d36-5b15-9f97-29c240641dc6'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Ich schicke dir die Adresse, damit du mich leicht findest.', 'I''m sending you the address so that you can find me easily.', 'damit du mich leicht findest', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'Different subjects (ich schicke / du findest), so damit is required.', 'Verschiedene Subjekte (ich schicke / du findest), deshalb damit.', '{"Ich":"I","schicke":"send (schicken, Präsens, ich)","dir":"you (Dativ)","die":"the (feminine)","Adresse":"address","damit":"so that","du":"you","mich":"me (Akkusativ)","leicht":"easily","findest":"find (finden, Präsens, du)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'd3534758-0d36-5b15-9f97-29c240641dc6'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '2c1ee6df-ef7a-58e7-9d96-22e0aab7435c'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Es regnet stark, sodass wir zu Hause bleiben.', 'It''s raining hard, so we''re staying home.', 'sodass wir zu Hause bleiben', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'sodass introduces the result of the heavy rain.', 'sodass leitet die Folge des starken Regens ein.', '{"Es":"it","regnet":"rains (regnen, Präsens, es)","stark":"hard, strongly","sodass":"so that, with the result that","wir":"we","zu":"at (zu Hause = at home)","Hause":"home (Dativ, fixed expression)","bleiben":"stay (bleiben, Präsens, wir)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '2c1ee6df-ef7a-58e7-9d96-22e0aab7435c'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4d035cab-055b-5183-aee6-7e3f0438a485'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Ich hatte Fieber, sodass ein Arztbesuch nötig war.', 'I had a fever, so a doctor''s visit was necessary.', 'sodass ein Arztbesuch nötig war', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'sodass introduces the result: a fever led to a necessary doctor''s visit.', 'sodass leitet die Folge ein: Wegen Fieber war ein Arztbesuch nötig.', '{"Ich":"I","hatte":"had (haben, Präteritum, ich)","Fieber":"fever","sodass":"so that, with the result that","ein":"a (masculine, Nominativ)","Arztbesuch":"doctor''s visit","nötig":"necessary","war":"was (sein, Präteritum, er)"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4d035cab-055b-5183-aee6-7e3f0438a485'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '6fd506c3-3d9a-5a6b-9266-3bac85fc046d'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Die Prüfung war so schwer, dass viele Studenten durchgefallen sind.', 'The exam was so difficult that many students failed.', 'so schwer, dass viele Studenten durchgefallen sind', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'so emphasizes schwer; dass introduces the result, with durchgefallen sind in the Perfekt.', 'so betont schwer, dass leitet die Folge ein. durchgefallen sind steht im Perfekt.', '{"Die":"the (feminine)","Prüfung":"exam","war":"was (sein, Präteritum, sie)","so":"so","schwer":"difficult, hard","dass":"that","viele":"many","Studenten":"students","durchgefallen":"failed (Partizip II of durchfallen)","sind":"have (sein, Präsens, sie/plural — Perfekt auxiliary)"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '6fd506c3-3d9a-5a6b-9266-3bac85fc046d'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'f69a7315-ed17-531b-9ec2-c2d8b972f78a'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Falls es regnet, bleiben wir zu Hause.', 'If it rains, we''ll stay home.', 'Falls es regnet', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'falls states a condition; the Nebensatz comes first, so bleiben follows right after the comma.', 'falls nennt eine Bedingung. Der Nebensatz steht zuerst, deshalb folgt bleiben direkt nach dem Komma.', '{"Falls":"if, in case","es":"it","regnet":"rains (regnen, Präsens, es)","bleiben":"stay (bleiben, Präsens, wir)","wir":"we","zu":"at","Hause":"home"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'f69a7315-ed17-531b-9ec2-c2d8b972f78a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'c4a4338c-114f-504b-8e3a-671fcce398f9'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 'Ruf mich an, falls du Hilfe brauchst.', 'Call me if you need help.', 'falls du Hilfe brauchst', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'The main clause comes first here, as an imperative, followed by the falls-clause.', 'Hier steht der Hauptsatz zuerst, als Imperativ, danach folgt der falls-Satz.', '{"Ruf":"call (rufen, Imperativ, du — separable prefix an)","mich":"me (Akkusativ)","an":"separable prefix of anrufen","falls":"if, in case","du":"you","Hilfe":"help","brauchst":"need (brauchen, Präsens, du)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'c4a4338c-114f-504b-8e3a-671fcce398f9'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'f275d4ae-7ef1-5a72-b4eb-663287a45cf2'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Ich bin stark erkältet. Deshalb gehe ich heute zum Arzt.', 'I have a bad cold. That''s why I''m going to the doctor today.', 'Deshalb gehe ich heute zum Arzt', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'deshalb stands in position 1; the verb gehe follows immediately in position 2.', 'deshalb steht auf Position 1. Das Verb gehe steht direkt danach auf Position 2.', '{"Ich":"I","bin":"am (sein, Präsens, ich)","stark":"badly, strongly","erkältet":"have a cold (erkältet sein)","Deshalb":"that''s why, therefore","gehe":"go (gehen, Präsens, ich)","ich":"I","heute":"today","zum":"to the (zu + dem)","Arzt":"doctor"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'f275d4ae-7ef1-5a72-b4eb-663287a45cf2'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '32d4a5f8-756c-59d5-a8a2-fa105ff769ec'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Der Drucker im Büro ist kaputt. Deswegen arbeite ich heute von zu Hause.', 'The printer at the office is broken. That''s why I''m working from home today.', 'Deswegen arbeite ich heute von zu Hause', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'deswegen means the same as deshalb; the verb arbeite stays in position 2.', 'deswegen bedeutet dasselbe wie deshalb. Das Verb arbeite steht auf Position 2.', '{"Der":"the (masculine)","Drucker":"printer","im":"in the (in + dem)","Büro":"office","ist":"is (sein, Präsens, er/sie/es)","kaputt":"broken","Deswegen":"that''s why, therefore","arbeite":"work (arbeiten, Präsens, ich)","ich":"I","heute":"today","von":"from","zu":"at (zu Hause = at home)","Hause":"home"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '32d4a5f8-756c-59d5-a8a2-fa105ff769ec'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '55de64b9-0f81-5820-b72e-d5df4cc7fdf2'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Die Miete steigt jedes Jahr. Darum suchen wir eine neue Wohnung.', 'The rent goes up every year. That''s why we''re looking for a new apartment.', 'Darum suchen wir eine neue Wohnung', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'darum is a third way to say deshalb; the verb suchen follows right after it.', 'darum ist eine dritte Möglichkeit für deshalb. Das Verb suchen steht direkt nach darum.', '{"Die":"the (feminine)","Miete":"rent","steigt":"rises (steigen, Präsens, es/sie)","jedes":"every (neuter)","Jahr":"year","Darum":"that''s why, therefore","suchen":"look for (suchen, Präsens, wir)","wir":"we","eine":"a (feminine, Akkusativ)","neue":"new","Wohnung":"apartment"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '55de64b9-0f81-5820-b72e-d5df4cc7fdf2'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0438f175-9ac1-5a60-9573-b571bdfe8735'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Der Kurs ist teuer. Trotzdem melde ich mich dafür an.', 'The course is expensive. Nevertheless, I''m signing up for it.', 'Trotzdem melde ich mich dafür an', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'trotzdem expresses a contrast but stays a main clause: the verb melde is in position 2.', 'trotzdem drückt einen Gegensatz aus, aber es bleibt ein Hauptsatz: Verb melde auf Position 2.', '{"Der":"the (masculine)","Kurs":"course","ist":"is (sein, Präsens, er/sie/es)","teuer":"expensive","Trotzdem":"nevertheless, despite that","melde":"sign up (sich anmelden, Präsens, ich)","ich":"I","mich":"myself (reflexive, Akkusativ)","dafür":"for it","an":"separable prefix of anmelden"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0438f175-9ac1-5a60-9573-b571bdfe8735'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '456a1fb9-3ae4-5fff-9733-306016167bdc'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Die Wohnung ist klein. Außerdem gibt es keinen Aufzug.', 'The apartment is small. Besides, there''s no elevator.', 'Außerdem gibt es keinen Aufzug', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'außerdem adds one more reason or argument to the first sentence.', 'außerdem fügt einen weiteren Grund oder ein weiteres Argument hinzu.', '{"Die":"the (feminine)","Wohnung":"apartment","ist":"is (sein, Präsens, er/sie/es)","klein":"small","Außerdem":"besides, in addition","gibt":"there is (es gibt, Präsens)","es":"it (part of es gibt)","keinen":"no, not any (masculine, Akkusativ)","Aufzug":"elevator"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '456a1fb9-3ae4-5fff-9733-306016167bdc'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'b52a0225-5bc3-5cbd-8bd9-da2a0958d659'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Schicken Sie das Formular bis Freitag zurück. Sonst ist Ihr Antrag ungültig.', 'Send the form back by Friday. Otherwise your application is invalid.', 'Sonst ist Ihr Antrag ungültig', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'sonst names a negative consequence if something does not happen.', 'sonst nennt eine negative Folge, wenn etwas nicht passiert.', '{"Schicken":"send (schicken, Imperativ, Sie-Form)","Sie":"you (formal)","das":"the (neuter, Akkusativ)","Formular":"form","bis":"by, until","Freitag":"Friday","zurück":"back (separable prefix of zurückschicken)","Sonst":"otherwise","ist":"is (sein, Präsens, er/sie/es)","Ihr":"your (formal, possessive)","Antrag":"application","ungültig":"invalid"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'b52a0225-5bc3-5cbd-8bd9-da2a0958d659'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5042f549-3427-584b-84b8-c6e5edc1e11e'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Wir packen die Koffer. Dann fahren wir zum Flughafen.', 'We pack our suitcases. Then we drive to the airport.', 'Dann fahren wir zum Flughafen', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'dann shows the order of steps; the verb fahren stays in position 2.', 'dann zeigt die Reihenfolge der Schritte. Das Verb fahren steht auf Position 2.', '{"Wir":"we","packen":"pack (packen, Präsens, wir)","die":"the (plural, Akkusativ)","Koffer":"suitcases","Dann":"then","fahren":"drive (fahren, Präsens, wir)","wir":"we","zum":"to the (zu + dem)","Flughafen":"airport"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5042f549-3427-584b-84b8-c6e5edc1e11e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '124497f9-c8cc-5438-b3c9-6c553829e04b'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Zuerst feiern wir zu Hause. Danach gehen alle noch in eine Bar.', 'First we celebrate at home. After that everyone still goes to a bar.', 'Danach gehen alle noch in eine Bar', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'danach describes the next step in a sequence of events.', 'danach beschreibt den nächsten Schritt in einer Reihenfolge.', '{"Zuerst":"first, at first","feiern":"celebrate (feiern, Präsens, wir)","wir":"we","zu":"at (zu Hause = at home)","Hause":"home","Danach":"after that","gehen":"go (gehen, Präsens, sie/alle)","alle":"everyone","noch":"still, additionally","in":"to, into","eine":"a (feminine, Akkusativ)","Bar":"bar"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '124497f9-c8cc-5438-b3c9-6c553829e04b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'a93b66d7-f8cc-553a-968d-abdcee6cd9e7'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Er spart viel Wasser und schont dabei die Umwelt.', 'He saves a lot of water and thereby protects the environment.', 'schont dabei die Umwelt', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'dabei sits mid-sentence, right after the verb schont.', 'dabei steht mitten im Satz, direkt nach dem Verb schont.', '{"Er":"he","spart":"saves (sparen, Präsens, er)","viel":"a lot of","Wasser":"water","und":"and","schont":"protects (schonen, Präsens, er)","dabei":"thereby, while doing so","die":"the (feminine, Akkusativ)","Umwelt":"environment"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'a93b66d7-f8cc-553a-968d-abdcee6cd9e7'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'f4b16205-3738-5f55-9795-7f7f164a2329'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 'Mein Bruder mag laute Musik. Dagegen höre ich lieber ruhige Musik.', 'My brother likes loud music. I, in contrast, prefer listening to quiet music.', 'Dagegen höre ich lieber ruhige Musik', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'dagegen sets up a contrast between two people or things.', 'dagegen stellt einen Gegensatz zwischen zwei Personen oder Dingen dar.', '{"Mein":"my (masculine)","Bruder":"brother","mag":"likes (mögen, Präsens, er)","laute":"loud","Musik":"music","Dagegen":"in contrast, on the other hand","höre":"listen to (hören, Präsens, ich)","ich":"I","lieber":"rather, prefer to","ruhige":"quiet, calm"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'f4b16205-3738-5f55-9795-7f7f164a2329'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4e560f5b-af3e-56d0-89a3-c9872e4c1b6a'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Wir fahren entweder mit dem Zug oder mit dem Bus.', 'We''re traveling either by train or by bus.', 'entweder mit dem Zug oder mit dem Bus', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'entweder and oder connect two options; the normal word order does not change here.', 'entweder und oder verbinden zwei Möglichkeiten. Die Wortstellung bleibt normal.', '{"Wir":"we","fahren":"travel (fahren, Präsens, wir)","entweder":"either","mit":"with","dem":"the (Dativ, masc./neut.)","Zug":"train","oder":"or","Bus":"bus"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4e560f5b-af3e-56d0-89a3-c9872e4c1b6a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '2f67937a-0dad-53d1-ab87-f0eaccc0aa51'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Entweder bleibst du im Büro, oder du arbeitest zu Hause.', 'Either you stay at the office, or you work from home.', 'Entweder bleibst du im Büro, oder du arbeitest zu Hause', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'entweder opens the sentence, so the verb bleibst follows immediately (inversion).', 'entweder steht am Satzanfang, deshalb steht das Verb bleibst direkt danach.', '{"Entweder":"either","bleibst":"stay (bleiben, Präsens, du)","du":"you","im":"in the (in + dem)","Büro":"office","oder":"or","arbeitest":"work (arbeiten, Präsens, du)","zu":"to","Hause":"home (fixed phrase zu Hause)"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '2f67937a-0dad-53d1-ab87-f0eaccc0aa51'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '8f698bae-0c8d-523c-8cc6-e4ea8f658799'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Der Kurs ist nicht nur günstig, sondern auch praktisch.', 'The course is not only affordable, but also practical.', 'nicht nur günstig, sondern auch praktisch', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'nicht nur … sondern auch connects two adjectives; with two equally weighted qualities, auch stays in.', 'nicht nur … sondern auch verbindet zwei Adjektive. Bei gleichwertigen Eigenschaften bleibt „auch“ immer dabei.', '{"Der":"the (masc.)","Kurs":"course","ist":"is","nicht":"not","nur":"only","günstig":"affordable","sondern":"but (rather)","auch":"also","praktisch":"practical"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '8f698bae-0c8d-523c-8cc6-e4ea8f658799'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '1e51a7f8-aa12-5763-bd6b-95e88978d73a'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Die Ärztin untersucht nicht nur das Herz, sondern auch die Lunge.', 'The doctor examines not only the heart, but also the lungs.', 'nicht nur das Herz, sondern auch die Lunge', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'Here nicht nur … sondern auch connects two accusative objects.', 'nicht nur … sondern auch verbindet hier zwei Objekte im Akkusativ.', '{"Die":"the (fem.)","Ärztin":"doctor (female)","untersucht":"examines (untersuchen, Präsens, sie)","nicht":"not","nur":"only","das":"the (neut.)","Herz":"heart","sondern":"but","auch":"also","die":"the (fem., second occurrence)","Lunge":"lung"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '1e51a7f8-aa12-5763-bd6b-95e88978d73a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'b08e4257-8042-5639-ae34-02caa4ca73b0'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Sowohl die Küche als auch das Bad sind neu.', 'Both the kitchen and the bathroom are new.', 'Sowohl die Küche als auch das Bad', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'sowohl … als auch together form the subject; the verb sind follows in normal position.', 'sowohl … als auch bildet zusammen das Subjekt. Das Verb sind steht danach.', '{"Sowohl":"both","die":"the (fem.)","Küche":"kitchen","als":"as","auch":"also","das":"the (neut.)","Bad":"bathroom","sind":"are (sein, Präsens, sie/plural)","neu":"new"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'b08e4257-8042-5639-ae34-02caa4ca73b0'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'c005c350-4255-5c95-bf8d-c82b5801d9e7'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Ich mag sowohl Zugreisen als auch Busreisen.', 'I like both train trips and bus trips.', 'sowohl Zugreisen als auch Busreisen', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'Here sowohl … als auch connects two objects without an article.', 'sowohl … als auch verbindet hier zwei Objekte ohne Artikel.', '{"Ich":"I","mag":"like (mögen, Präsens, ich)","sowohl":"both","Zugreisen":"train trips","als":"as","auch":"also","Busreisen":"bus trips"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'c005c350-4255-5c95-bf8d-c82b5801d9e7'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '49f4e89f-26a8-574e-81a2-176bcb5ae8b1'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Der Patient hat weder Fieber noch Husten.', 'The patient has neither fever nor a cough.', 'weder Fieber noch Husten', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'weder … noch negates two nouns together; oder never follows weder.', 'weder … noch verneint zwei Nomen zusammen. Nach weder kommt nie oder.', '{"Der":"the (masc.)","Patient":"patient","hat":"has (haben, Präsens, er)","weder":"neither","Fieber":"fever","noch":"nor","Husten":"cough"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '49f4e89f-26a8-574e-81a2-176bcb5ae8b1'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '7ddfb3fd-7fe9-5466-ac81-83b388ab965a'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Weder der Lärm noch die Miete stört mich.', 'Neither the noise nor the rent bothers me.', 'Weder der Lärm noch die Miete stört mich', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'weder … noch forms the subject here; the verb typically stays singular, though the plural is equally standard.', 'weder … noch bildet das Subjekt. Der Singular ist danach üblich; der Plural ist auch möglich.', '{"Weder":"neither","der":"the (masc.)","Lärm":"noise","noch":"nor","die":"the (fem.)","Miete":"rent","stört":"bothers (stören, Präsens, es/sie)","mich":"me"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '7ddfb3fd-7fe9-5466-ac81-83b388ab965a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '330cd6e4-466e-5ee2-aecf-c6ef52cbc6ca'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Zwar ist die Wohnung klein, aber sie ist günstig.', 'Admittedly the apartment is small, but it''s affordable.', 'Zwar ist die Wohnung klein, aber sie ist günstig', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'zwar opens the sentence, so the verb ist follows immediately (inversion).', 'zwar steht am Anfang, deshalb steht das Verb ist direkt danach.', '{"Zwar":"admittedly","ist":"is","die":"the (fem.)","Wohnung":"apartment","klein":"small","aber":"but","sie":"it/she","günstig":"affordable"}'::jsonb, 2, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '330cd6e4-466e-5ee2-aecf-c6ef52cbc6ca'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'b55a25b7-75b1-53d0-9cdd-8c8c4cc4938e'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 'Die Arbeit ist zwar anstrengend, aber sie macht Spaß.', 'The work is admittedly exhausting, but it''s fun.', 'ist zwar anstrengend, aber sie macht Spaß', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'Here zwar stands after the verb, because position one is already filled by Die Arbeit.', 'zwar steht hier nach dem Verb, denn Position eins ist schon besetzt.', '{"Die":"the (fem.)","Arbeit":"work","ist":"is","zwar":"admittedly","anstrengend":"exhausting","aber":"but","sie":"it","macht":"makes (machen, Präsens, sie)","Spaß":"fun"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'b55a25b7-75b1-53d0-9cdd-8c8c4cc4938e'::uuid);

-- Exercises
INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '936bd1ac-18cc-5c75-a2b4-399077011640'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'fill_blank', '___ ich zum Vorstellungsgespräch kam, war ich sehr aufgeregt.', 'Fill in the connector: When I came to the job interview, I was very excited. (a single past event — als or wenn?)', NULL, 'Als', '["Als"]'::jsonb, 'A single past event needs als, not wenn.', 'Ein einmaliges Ereignis in der Vergangenheit braucht als, nicht wenn.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'kam describes a single event, so als is required.', 'kam ist ein einmaliges Ereignis, deshalb als.', 'als vs. wenn: The Key Difference'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '936bd1ac-18cc-5c75-a2b4-399077011640'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9c498a16-7d97-5ae3-b3ec-403a657c55ed'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'multiple_choice', 'Welches Wort passt? Jedes Mal, ___ wir Besuch hatten, gab es Kuchen.', 'Choose the connector: Every time we had visitors, there was cake. (a repeated past action)', '["als","wenn","bevor","nachdem"]'::jsonb, 'wenn', NULL, 'A repeated past action needs wenn, not als.', 'Eine wiederholte Handlung in der Vergangenheit braucht wenn, nicht als.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Jedes Mal signals repetition — only wenn fits.', 'Jedes Mal signalisiert Wiederholung — nur wenn passt.', 'als vs. wenn: The Key Difference'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9c498a16-7d97-5ae3-b3ec-403a657c55ed'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c382b992-a2f4-55a5-bde5-c3cb86247274'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'fill_blank', '___ ich den Mietvertrag unterschreibe, lese ich die Bedingungen genau.', 'Fill in the connector: Before I sign the rental contract, I read the terms carefully.', NULL, 'Bevor', '["Bevor"]'::jsonb, 'bevor shows that the reading happens before the signing.', 'bevor zeigt: Das Lesen passiert vor dem Unterschreiben.', NULL, 3, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only bevor expresses ''before''.', 'Nur bevor drückt „vorher“ aus.', 'bevor and nachdem: Building the Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c382b992-a2f4-55a5-bde5-c3cb86247274'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4e9aa2a3-e1e7-5901-a490-cfa6d66f1d60'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence has correct word order for: After I had sent the application, I went home.', '["Nachdem ich die Bewerbung abgeschickt hatte, ging ich nach Hause.","Nachdem ich habe die Bewerbung abgeschickt, ging ich nach Hause.","Nachdem ich die Bewerbung abgeschickt hatte ging ich nach Hause.","Nachdem ich die Bewerbung abgeschickt habe, ging ich nach Hause."]'::jsonb, 'Nachdem ich die Bewerbung abgeschickt hatte, ging ich nach Hause.', NULL, 'abgeschickt hatte goes to the very end of the nachdem-clause; the main clause is in the Präteritum, so the nachdem-clause needs the Plusquamperfekt.', 'abgeschickt hatte steht ganz am Ende des nachdem-Satzes. Der Hauptsatz steht im Präteritum, deshalb Plusquamperfekt.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only this version has Plusquamperfekt before Präteritum, verb-final in the subordinate clause, and the comma.', 'Nur diese Version hat Plusquamperfekt vor Präteritum, Verb-Ende im Nebensatz und ein Komma.', 'nachdem + Plusquamperfekt: One Step Earlier'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4e9aa2a3-e1e7-5901-a490-cfa6d66f1d60'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f5432dee-abfb-5956-8098-3d8935348cdd'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'fill_blank', 'Nachdem der Patient die Tabletten ___, ging es ihm besser. (nehmen, Plusquamperfekt)', 'Fill in the verb form: After the patient had taken the tablets, he felt better. (nehmen, Plusquamperfekt)', NULL, 'genommen hatte', '["genommen hatte"]'::jsonb, 'Plusquamperfekt = hatte + past participle. It stands at the very end of the nachdem-clause.', 'Plusquamperfekt = hatte + Partizip II. Es steht ganz am Ende des nachdem-Satzes.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'nehmen forms its perfect with haben: genommen hatte.', 'nehmen bildet das Perfekt mit haben: genommen hatte.', 'nachdem + Plusquamperfekt: One Step Earlier'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f5432dee-abfb-5956-8098-3d8935348cdd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9eda6159-8259-53bb-804b-c9690351d80f'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct for: After I''ve passed the exam, I celebrate with colleagues. (main clause in the present)', '["Nachdem ich die Prüfung bestanden habe, feiere ich mit Kollegen.","Nachdem ich die Prüfung bestanden hatte, feiere ich mit Kollegen.","Nachdem ich die Prüfung bestehe, feiere ich mit Kollegen.","Nachdem ich bestanden habe die Prüfung, feiere ich mit Kollegen."]'::jsonb, 'Nachdem ich die Prüfung bestanden habe, feiere ich mit Kollegen.', NULL, 'The main clause is in the present, so the nachdem-clause needs the Perfekt, not the Plusquamperfekt.', 'Der Hauptsatz steht im Präsens, deshalb braucht der nachdem-Satz das Perfekt, nicht das Plusquamperfekt.', NULL, 6, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only this version has the correct tense pairing (Perfekt before Präsens) and correct word order.', 'Nur diese Version hat die richtige Zeitstufe (Perfekt vor Präsens) und die richtige Wortstellung.', 'nachdem + Plusquamperfekt: One Step Earlier'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9eda6159-8259-53bb-804b-c9690351d80f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a2213996-e7ec-5ef3-be3b-a5046b5584ea'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'fill_blank', '___ ich auf meinen Termin warte, fülle ich das Formular aus.', 'Fill in the connector: While I wait for my appointment, I fill out the form.', NULL, 'Während', '["Während"]'::jsonb, 'während shows two actions happening at the same time.', 'während zeigt zwei Handlungen zur gleichen Zeit.', NULL, 7, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Both actions happen at the same time — exactly what während expresses.', 'Beide Handlungen laufen gleichzeitig — das ist genau während.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a2213996-e7ec-5ef3-be3b-a5046b5584ea'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8d573b4a-345b-5062-a9ad-f8795d36dbe1'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'fill_blank', 'Wir warten am Flughafen, ___ das Flugzeug endlich startet.', 'Fill in the connector: We wait at the airport until the plane finally takes off.', NULL, 'bis', '["bis"]'::jsonb, 'bis marks the endpoint of the waiting.', 'bis zeigt den Endpunkt des Wartens.', NULL, 8, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'endlich makes the endpoint explicit — only bis fits this waiting-until-then meaning.', 'endlich macht den Endpunkt deutlich — nur bis passt zu diesem Warten-bis-dahin.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8d573b4a-345b-5062-a9ad-f8795d36dbe1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b394a362-7d0b-5fdf-9ccb-e464db13ab38'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'multiple_choice', 'Welches Wort passt? ___ ich den Deutschkurs besuche, verstehe ich viel mehr.', 'Choose the connector: Since I''ve been attending the German course, I understand much more.', '["Seit","Bis","Bevor","Nachdem"]'::jsonb, 'Seit', NULL, 'seit marks a start in the past that still has an effect today.', 'seit zeigt einen Start in der Vergangenheit mit Wirkung bis heute.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only seit fits the meaning ''from that point until now''.', 'Nur seit passt zur Bedeutung „ab diesem Zeitpunkt bis jetzt“.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b394a362-7d0b-5fdf-9ccb-e464db13ab38'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9292b889-9781-58ca-a029-885d8abc4fc7'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'error_correction', 'Finde den Fehler: Nachdem ich habe die Nachrichten gelesen, rufe ich meine Schwester an.', 'Correct the word order. The Perfekt verb must stand at the very end of the nachdem-clause.', NULL, 'Nachdem ich die Nachrichten gelesen habe, rufe ich meine Schwester an.', '["Nachdem ich die Nachrichten gelesen habe, rufe ich meine Schwester an.","Nachdem ich die Nachrichten gelesen habe, rufe ich meine Schwester an"]'::jsonb, 'gelesen habe stays together at the very end of the nachdem-clause.', 'gelesen habe steht zusammen ganz am Ende des nachdem-Satzes.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'habe cannot stand before the participle — both belong at the end of the clause, and the main clause stays in the present.', 'habe darf nicht vor dem Partizip stehen — beide gehören ans Satzende, und der Hauptsatz bleibt im Präsens.', 'nachdem + Plusquamperfekt: One Step Earlier'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9292b889-9781-58ca-a029-885d8abc4fc7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f5df9ce9-d96a-558c-8819-3b1b6e57e43c'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'error_correction', 'Finde den Fehler: Wenn ich letztes Jahr nach Berlin fuhr, blieb ich bei Freunden.', 'Correct the connector. This describes one specific event last year, not a repeated one.', NULL, 'Als ich letztes Jahr nach Berlin fuhr, blieb ich bei Freunden.', '["Als ich letztes Jahr nach Berlin fuhr, blieb ich bei Freunden.","Als ich letztes Jahr nach Berlin fuhr, blieb ich bei Freunden"]'::jsonb, 'letztes Jahr signals a single event — that needs als, not wenn.', 'letztes Jahr zeigt ein einmaliges Ereignis — das braucht als, nicht wenn.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only als fits a single event in the past.', 'Nur als passt zu einem einmaligen Ereignis in der Vergangenheit.', 'als vs. wenn: The Key Difference'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f5df9ce9-d96a-558c-8819-3b1b6e57e43c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3e9583ef-5c4b-5813-9b21-786425fa632f'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct for: Before the party starts, we decorate the room.', '["Bevor das Fest beginnt, schmücken wir den Raum.","Bevor das Fest beginnt schmücken wir den Raum.","Bevor beginnt das Fest, schmücken wir den Raum.","Das Fest beginnt, bevor wir den Raum schmücken."]'::jsonb, 'Bevor das Fest beginnt, schmücken wir den Raum.', NULL, 'Subordinate clause first: comma, then the verb schmücken right after.', 'Nebensatz zuerst: Komma, dann Verb schmücken direkt danach.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only this version has the comma, correct word order in the subordinate clause, and the correct order of events.', 'Nur diese Version hat Komma, richtige Wortstellung im Nebensatz und die richtige Reihenfolge der Ereignisse.', 'bevor and nachdem: Building the Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3e9583ef-5c4b-5813-9b21-786425fa632f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd1fa4e89-a439-594b-9e5c-49e21dd535f4'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 4, 'multiple_choice', 'Welches Wort passt? Wir sammeln Unterschriften, ___ die Stadt reagiert.', 'Choose the connector: We collect signatures until the city reacts.', '["bis","während","seit","als"]'::jsonb, 'bis', NULL, 'bis marks the endpoint of the action.', 'bis markiert den Endpunkt der Handlung.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'bis expresses exactly this endpoint: the city''s reaction.', 'bis beschreibt genau diesen Endpunkt: die Reaktion der Stadt.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd1fa4e89-a439-594b-9e5c-49e21dd535f4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '61e728fa-4b11-50f6-a779-6be5d775771b'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [als / der Krankenwagen / kam / der Patient / starke Schmerzen / hatte]', 'Write the sentence: When the ambulance came, the patient had severe pain. (kam and hatte are already given — build the correct word order; start with Als)', NULL, 'Als der Krankenwagen kam, hatte der Patient starke Schmerzen.', '["Als der Krankenwagen kam, hatte der Patient starke Schmerzen.","Als der Krankenwagen kam, hatte der Patient starke Schmerzen"]'::jsonb, 'als describes a single event: the ambulance came exactly once.', 'als beschreibt ein einmaliges Ereignis: Der Krankenwagen kam genau einmal.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The ambulance came exactly once — that''s why it''s als, not wenn.', 'Der Krankenwagen kam genau einmal — deshalb als, nicht wenn.', 'als vs. wenn: The Key Difference'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '61e728fa-4b11-50f6-a779-6be5d775771b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '945c02fb-9c8e-5eac-b06e-dd922c2aee45'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wenn / es / heiß / sein / ich / genug Wasser / trinken]', 'Write the sentence: When it''s hot, I drink enough water. (Präsens; start with Wenn)', NULL, 'Wenn es heiß ist, trinke ich genug Wasser.', '["Wenn es heiß ist, trinke ich genug Wasser.","Wenn es heiß ist, trinke ich genug Wasser"]'::jsonb, 'wenn describes a general habit here, not a one-time action.', 'wenn beschreibt hier eine allgemeine Gewohnheit, keine einmalige Handlung.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'A general habit needs wenn, not als.', 'Eine allgemeine Gewohnheit braucht wenn, nicht als.', 'als vs. wenn: The Key Difference'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '945c02fb-9c8e-5eac-b06e-dd922c2aee45'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f6e45678-ffab-5050-b50d-df3e4afb0935'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [bevor / ich / einziehen / ich / die Wohnung / renovieren]', 'Write the sentence: Before I move in, I renovate the apartment. (Präsens; start with Bevor)', NULL, 'Bevor ich einziehe, renoviere ich die Wohnung.', '["Bevor ich einziehe, renoviere ich die Wohnung.","Bevor ich einziehe, renoviere ich die Wohnung"]'::jsonb, 'bevor shows that the renovation happens before the move-in.', 'bevor zeigt: Die Renovierung passiert vor dem Einzug.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subordinate clause first, then the comma and the verb renoviere.', 'Nebensatz zuerst, danach Komma und Verb renoviere.', 'bevor and nachdem: Building the Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f6e45678-ffab-5050-b50d-df3e4afb0935'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '14dccc31-267e-54b5-bff5-08b76aa91be2'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [nachdem / ich / das Büro / verlassen / mein Kollege / zurückkommen]', 'Write the sentence: After I had left the office, my colleague came back. (Plusquamperfekt in the nachdem-clause, Präteritum in the main clause; start with Nachdem)', NULL, 'Nachdem ich das Büro verlassen hatte, kam mein Kollege zurück.', '["Nachdem ich das Büro verlassen hatte, kam mein Kollege zurück.","Nachdem ich das Büro verlassen hatte, kam mein Kollege zurück"]'::jsonb, 'verlassen hatte is the Plusquamperfekt: it stands at the very end of the nachdem-clause.', 'verlassen hatte ist das Plusquamperfekt: Es steht ganz am Ende des nachdem-Satzes.', NULL, 4, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The main clause is in the Präteritum (kam), so the nachdem-clause needs the Plusquamperfekt.', 'Der Hauptsatz steht im Präteritum (kam), deshalb braucht der nachdem-Satz das Plusquamperfekt.', 'nachdem + Plusquamperfekt: One Step Earlier'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '14dccc31-267e-54b5-bff5-08b76aa91be2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3acca129-d37b-55fc-825c-777de69b46dc'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [nachdem / ich / das Formular / ausfüllen / ich / es / am Schalter / abgeben]', 'Write the sentence: After I''ve filled out the form, I hand it in at the counter. (Perfekt in the nachdem-clause, Präsens in the main clause; start with Nachdem)', NULL, 'Nachdem ich das Formular ausgefüllt habe, gebe ich es am Schalter ab.', '["Nachdem ich das Formular ausgefüllt habe, gebe ich es am Schalter ab.","Nachdem ich das Formular ausgefüllt habe, gebe ich es am Schalter ab"]'::jsonb, 'ausgefüllt habe is the Perfekt: the main clause is in the present, so no Plusquamperfekt is needed.', 'ausgefüllt habe ist das Perfekt: Der Hauptsatz steht im Präsens, deshalb kein Plusquamperfekt.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'A present-tense main clause needs Perfekt (not Plusquamperfekt) in the nachdem-clause.', 'Präsens im Hauptsatz braucht Perfekt (nicht Plusquamperfekt) im nachdem-Satz.', 'nachdem + Plusquamperfekt: One Step Earlier'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3acca129-d37b-55fc-825c-777de69b46dc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f1a546b9-b577-5bff-8852-156a99057c2b'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [während / ich / krank / sein / meine Kollegin / meine Arbeit / übernehmen]', 'Write the sentence: While I''m sick, my colleague takes over my work. (Präsens; start with Während)', NULL, 'Während ich krank bin, übernimmt meine Kollegin meine Arbeit.', '["Während ich krank bin, übernimmt meine Kollegin meine Arbeit.","Während ich krank bin, übernimmt meine Kollegin meine Arbeit"]'::jsonb, 'während shows two actions happening at the same time.', 'während zeigt zwei Handlungen zur gleichen Zeit.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subordinate clause first, then the comma and the verb übernimmt.', 'Nebensatz zuerst, danach Komma und das Verb übernimmt.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f1a546b9-b577-5bff-8852-156a99057c2b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '789af9a3-a7e1-51d1-ad2a-f0ffefa1f183'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Gäste / tanzen / während / die Band / spielen]', 'Write the sentence: The guests dance while the band plays. (Präsens; start with Die Gäste)', NULL, 'Die Gäste tanzen, während die Band spielt.', '["Die Gäste tanzen, während die Band spielt.","Die Gäste tanzen, während die Band spielt"]'::jsonb, 'Here the main clause comes first, followed by a comma and the während-clause.', 'Hier steht der Hauptsatz zuerst, danach folgt der während-Satz mit Komma.', NULL, 7, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Main clause first: the comma comes right before während.', 'Hauptsatz zuerst: Komma direkt vor während.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '789af9a3-a7e1-51d1-ad2a-f0ffefa1f183'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '47bd54b5-da00-5413-8013-16fdc6c15f7f'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Kinder / spielen / bis / es / dunkel / werden]', 'Write the sentence: The children play until it gets dark. (Präsens; start with Die Kinder)', NULL, 'Die Kinder spielen, bis es dunkel wird.', '["Die Kinder spielen, bis es dunkel wird.","Die Kinder spielen, bis es dunkel wird"]'::jsonb, 'bis marks the endpoint: the playing ends when it gets dark.', 'bis markiert den Endpunkt: Das Spielen endet, wenn es dunkel wird.', NULL, 8, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Main clause first: the comma comes right before bis.', 'Hauptsatz zuerst: Komma direkt vor bis.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '47bd54b5-da00-5413-8013-16fdc6c15f7f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8fa61a15-e6f5-57b5-9244-22eef4957539'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [seit / ich / Deutsch / lernen / ich / mehr Bücher / lesen]', 'Write the sentence: Since I''ve been learning German, I read more books. (Präsens; start with Seit)', NULL, 'Seit ich Deutsch lerne, lese ich mehr Bücher.', '["Seit ich Deutsch lerne, lese ich mehr Bücher.","Seit ich Deutsch lerne, lese ich mehr Bücher","Seitdem ich Deutsch lerne, lese ich mehr Bücher.","Seitdem ich Deutsch lerne, lese ich mehr Bücher"]'::jsonb, 'seit marks the start in the past; its effect continues into the present.', 'seit markiert den Start in der Vergangenheit, die Wirkung dauert bis heute an.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subordinate clause first, then the comma and the verb lese.', 'Nebensatz zuerst, danach Komma und das Verb lese.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8fa61a15-e6f5-57b5-9244-22eef4957539'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'edba6a86-78ee-5811-9518-6f2fe734a110'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [als / ich / in die neue Stadt / kam / ich / noch niemanden / kannte]', 'Write the sentence: When I came to the new city, I didn''t know anyone yet. (kam and kannte are already given — build the correct word order; start with Als)', NULL, 'Als ich in die neue Stadt kam, kannte ich noch niemanden.', '["Als ich in die neue Stadt kam, kannte ich noch niemanden.","Als ich in die neue Stadt kam, kannte ich noch niemanden"]'::jsonb, 'als describes a single event: moving to the new city.', 'als beschreibt ein einmaliges Ereignis: der Umzug in die neue Stadt.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'A single event (the move) needs als, not wenn.', 'Ein einmaliges Ereignis (der Umzug) braucht als, nicht wenn.', 'als vs. wenn: The Key Difference'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'edba6a86-78ee-5811-9518-6f2fe734a110'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'dc68f9b2-3380-5369-9dc4-708306c93c7a'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wenn / wir / genug Zeit / haben / wir / nach Italien / fahren]', 'Write the sentence: When we have enough time, we''ll drive to Italy. (Präsens with future meaning; start with Wenn)', NULL, 'Wenn wir genug Zeit haben, fahren wir nach Italien.', '["Wenn wir genug Zeit haben, fahren wir nach Italien.","Wenn wir genug Zeit haben, fahren wir nach Italien"]'::jsonb, 'wenn refers to the future here: the trip depends on having free time.', 'wenn steht hier für die Zukunft: Die Reise hängt von der freien Zeit ab.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subordinate clause first, then the comma and the verb fahren.', 'Nebensatz zuerst, danach Komma und das Verb fahren.', 'als vs. wenn: The Key Difference'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dc68f9b2-3380-5369-9dc4-708306c93c7a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fa63ded8-969c-5e1c-9925-8bad362db85a'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'error_correction', 'Finde den Fehler: Während ich das Formular ausfülle spricht die Beamtin mit einer Kollegin.', 'Correct the punctuation. A comma always comes before a subordinate clause.', NULL, 'Während ich das Formular ausfülle, spricht die Beamtin mit einer Kollegin.', '["Während ich das Formular ausfülle, spricht die Beamtin mit einer Kollegin.","Während ich das Formular ausfülle, spricht die Beamtin mit einer Kollegin"]'::jsonb, 'A comma always comes before a subordinate clause, even at the start of the sentence.', 'Vor jedem Nebensatz steht ein Komma, auch wenn er am Satzanfang steht.', NULL, 12, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only the comma was missing — the word order was already correct.', 'Nur das Komma fehlt — die Wortstellung ist schon richtig.', 'während, bis, seit: while, until, since'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fa63ded8-969c-5e1c-9925-8bad362db85a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c5cd6e8e-18be-547a-aac1-2c3814a8fcbb'::uuid, '4279ffc8-aa42-5864-b7dc-d5b9a4b8b462'::uuid, 5, 'error_correction', 'Finde den Fehler: Bevor wir abfahren, wir kontrollieren die Reifen.', 'Correct the word order. After the comma, the verb comes immediately — before the subject.', NULL, 'Bevor wir abfahren, kontrollieren wir die Reifen.', '["Bevor wir abfahren, kontrollieren wir die Reifen.","Bevor wir abfahren, kontrollieren wir die Reifen"]'::jsonb, 'After the comma, the verb comes first, then the subject: kontrollieren wir.', 'Nach dem Komma steht zuerst das Verb, dann das Subjekt: kontrollieren wir.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The subordinate clause comes first, so the main clause''s verb follows immediately.', 'Der Nebensatz steht vorn, deshalb folgt direkt danach das Verb im Hauptsatz.', 'bevor and nachdem: Building the Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c5cd6e8e-18be-547a-aac1-2c3814a8fcbb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b4eef7e5-8a28-5e26-ab7f-32841ee0668a'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'fill_blank', '___ Peter müde ist, arbeitet er weiter. (Gegensatz)', 'Fill in the connector for a concession (Nebensatz first): Although Peter is tired, he keeps working.', NULL, 'Obwohl', '["Obwohl"]'::jsonb, 'The clause starts the sentence, so obwohl is capitalized as Obwohl.', 'Nebensatz zuerst: obwohl leitet den Satz ein. Am Satzanfang schreibst du es groß.', 'Am Satzanfang schreibst du den Konnektor groß.', 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Peter keeps working despite being tired — that''s a contrast, so obwohl is correct.', 'Peter arbeitet trotz seiner Müdigkeit weiter. Das ist ein Gegensatz, deshalb obwohl.', 'obwohl: Expressing Contrast'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b4eef7e5-8a28-5e26-ab7f-32841ee0668a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5f57a130-3b71-5426-8acb-2a4b3c29af48'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'fill_blank', 'Er lernt jeden Tag Vokabeln, ___ den Wortschatz zu verbessern. (Zweck, gleiches Subjekt)', 'Fill in the missing word: he learns AND he improves his vocabulary — the same subject does both.', NULL, 'um', '["um"]'::jsonb, 'The subject is the same in both parts (he learns, he improves), so um … zu is correct.', 'Das Subjekt ist in beiden Satzteilen gleich (er lernt, er verbessert). Deshalb um ... zu.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'With the same subject you use um … zu, not damit.', 'Bei gleichem Subjekt benutzt man um ... zu, nicht damit.', 'damit vs. um … zu: Same or Different Subject?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5f57a130-3b71-5426-8acb-2a4b3c29af48'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '60764daf-0839-56cd-b896-acd063755437'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'fill_blank', 'Die Mutter spricht laut, ___ ihr Sohn sie im Nebenzimmer hört. (Zweck, nicht Folge)', 'Fill in the connector: the mother speaks, but her son does the hearing — different subjects.', NULL, 'damit', '["damit"]'::jsonb, 'The subjects differ (the mother / her son), so damit is correct.', 'Das Subjekt ist unterschiedlich (die Mutter / ihr Sohn). Deshalb damit.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'um … zu doesn''t work here because the son, not the mother, is the one hearing.', 'um ... zu geht hier nicht, weil der Sohn und nicht die Mutter hört.', 'damit vs. um … zu: Same or Different Subject?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '60764daf-0839-56cd-b896-acd063755437'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '03a09c94-0eb6-5019-82aa-ec436260b830'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'fill_blank', 'Der Bus ist zu spät gekommen, ___ ich den Zug verpasst habe.', 'Fill in the connector for the result: The bus came too late, so I missed my train.', NULL, 'sodass', '["sodass","so dass"]'::jsonb, 'sodass introduces the result: the bus was late, and the result is the missed train.', 'sodass leitet die Folge ein: Der Bus kam spät. Die Folge: Ich habe den Zug verpasst.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sodass comes right after the comma and states the outcome.', 'sodass steht direkt nach dem Komma und beschreibt das Ergebnis.', 'sodass and so … dass: Expressing Result'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '03a09c94-0eb6-5019-82aa-ec436260b830'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '44089353-3407-592e-8734-48f4c278d09a'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'fill_blank', '___ du Fragen hast, ruf mich einfach an.', 'Fill in the connector for a condition: If you have questions, just call me.', NULL, 'Falls', '["Falls","Wenn"]'::jsonb, 'falls expresses a condition, like wenn. At the start of the sentence it is capitalized.', 'falls ist eine Bedingung, genau wie wenn. Am Satzanfang schreibst du es groß.', 'Am Satzanfang schreibst du den Konnektor groß.', 5, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'The speaker isn''t sure whether questions will come — that''s a condition.', 'Der Sprecher weiß nicht sicher, ob Fragen kommen. Das ist eine Bedingung.', 'falls: Expressing a Condition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '44089353-3407-592e-8734-48f4c278d09a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b97b0058-7bef-554b-affb-70ea159849cb'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'multiple_choice', 'Er kauft sich ein neues Auto, ___ er wenig Geld hat. Welcher Konnektor passt?', 'Choose the connector: He buys a new car although he has little money.', '["obwohl","weil","damit","falls"]'::jsonb, 'obwohl', NULL, 'Despite having little money he buys a car — that''s a contrast.', 'Er hat wenig Geld, aber er kauft ein Auto. Das ist ein Gegensatz.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'weil would state a reason, not a contrast; damit and falls don''t fit the meaning.', 'weil würde einen Grund nennen, nicht einen Gegensatz. damit und falls passen inhaltlich nicht.', 'obwohl: Expressing Contrast'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b97b0058-7bef-554b-affb-70ea159849cb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0132dabc-1fee-5cdf-8511-afa3183039ed'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence has correct word order? (Although it''s raining, I go for a walk.)', '["Obwohl es regnet, ich gehe spazieren.","Obwohl es regnet, gehe ich spazieren.","Obwohl regnet es, gehe ich spazieren.","Obwohl es regnet gehe ich spazieren."]'::jsonb, 'Obwohl es regnet, gehe ich spazieren.', NULL, 'After the comma the verb comes first, then the subject.', 'Nach dem Komma steht zuerst das Verb, dann das Subjekt.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options misplace the verb in the obwohl-clause, in the main clause, or drop the comma.', 'Die anderen Sätze haben das Verb falsch platziert oder das Komma vergessen.', 'obwohl: Expressing Contrast'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0132dabc-1fee-5cdf-8511-afa3183039ed'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1d461ff8-c1e8-5ee4-b70d-d33909477070'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct? (The mother buys her child a phone so that it can always reach her.)', '["Die Mutter kauft ihrem Kind ein Handy, damit es sie immer erreichen kann.","Die Mutter kauft ihrem Kind ein Handy, damit es sie immer erreichen zu können.","Die Mutter kauft ihrem Kind ein Handy, damit um es zu erreichen.","Die Mutter kauft ihrem Kind ein Handy, damit sie immer erreichen kann es."]'::jsonb, 'Die Mutter kauft ihrem Kind ein Handy, damit es sie immer erreichen kann.', NULL, 'The subjects differ (the mother buys, the child reaches), so damit is needed, not um … zu.', 'Die Subjekte sind unterschiedlich (die Mutter kauft, das Kind erreicht). Deshalb damit, nicht um ... zu.', NULL, 8, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Option 2 uses a zu-infinitive instead of a finite verb at the end, option 3 mixes damit and um, and option 4 has the wrong word order.', 'Option 2 hat einen Infinitiv mit zu statt eines Verbs am Ende. Option 3 mischt damit und um. Option 4 hat die falsche Wortstellung.', 'damit vs. um … zu: Same or Different Subject?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1d461ff8-c1e8-5ee4-b70d-d33909477070'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0d5fa6b6-f1cd-5f68-948a-8d437fc389d4'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'fill_blank', 'Der Kaffee war ___ heiß, dass ich mich verbrannt habe.', 'Fill in the missing word: The coffee was so hot that I burned myself.', NULL, 'so', '["so"]'::jsonb, 'so stands before the adjective; dass follows after it.', 'so steht vor dem Adjektiv, dass folgt danach.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'so … dass emphasizes just how hot the coffee was.', 'so ... dass betont, wie heiß der Kaffee war.', 'sodass and so … dass: Expressing Result'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0d5fa6b6-f1cd-5f68-948a-8d437fc389d4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3d34646d-18b3-5794-a8b9-19e7ae70292c'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'error_correction', 'Finde den Fehler: Ob wir Zeit haben, gehen wir spazieren.', 'Correct the connector. ob introduces a question, not a condition. (If we have time, we''ll go for a walk.)', NULL, 'Falls wir Zeit haben, gehen wir spazieren.', '["Falls wir Zeit haben, gehen wir spazieren.","Falls wir Zeit haben, gehen wir spazieren","Wenn wir Zeit haben, gehen wir spazieren.","Wenn wir Zeit haben, gehen wir spazieren"]'::jsonb, 'ob only fits an indirect question, not a condition. Here you need falls.', 'ob passt nur zu einer indirekten Frage, nicht zu einer Bedingung. Hier brauchst du falls.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only the connector was wrong; the word order was already correct.', 'Nur der Konnektor war falsch, die Wortstellung war schon richtig.', 'falls: Expressing a Condition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3d34646d-18b3-5794-a8b9-19e7ae70292c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8cffe771-215f-5cd4-bd87-74cfc2a1dcd8'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'fill_blank', 'Ich schreibe dem Kollegen eine Notiz, damit er nichts ___. (vergessen, Präsens, er)', 'Fill in the verb at the end: I write the colleague a note so that he doesn''t forget anything. (vergessen, present, er)', NULL, 'vergisst', '["vergisst"]'::jsonb, 'The verb vergisst stands at the very end of the damit-clause.', 'Das Verb vergisst steht ganz am Ende des damit-Satzes.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'damit sends the clause into verb-final order: nichts vergisst.', 'Nach damit folgt Verbendstellung: nichts vergisst.', 'damit vs. um … zu: Same or Different Subject?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8cffe771-215f-5cd4-bd87-74cfc2a1dcd8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b2585f80-a38a-5247-8bef-3002692a7b5d'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'fill_blank', 'Die Prüfung ist schwer, sodass ich viel üben ___. (müssen, Präsens, ich)', 'Fill in the modal at the end: The exam is hard, so I have to practice a lot. (müssen, present, ich)', NULL, 'muss', '["muss"]'::jsonb, 'With a modal verb the infinitive üben comes first, and the modal muss closes the clause.', 'Bei einem Modalverb steht der Infinitiv üben zuerst, das Modalverb muss ganz am Ende.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'üben muss is the correct order inside the subordinate clause.', 'üben muss ist die richtige Reihenfolge im Nebensatz.', 'sodass and so … dass: Expressing Result'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b2585f80-a38a-5247-8bef-3002692a7b5d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ffa277b8-4967-5650-bf96-cd4e7228bd18'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 4, 'multiple_choice', 'Er hat drei Kaffees getrunken, ___ er jetzt nicht schlafen kann. Welcher Konnektor passt?', 'Choose the connector: He drank three coffees, so now he can''t sleep.', '["sodass","obwohl","falls","damit"]'::jsonb, 'sodass', NULL, 'The three coffees are the cause; not being able to sleep is the result.', 'Die drei Kaffees sind die Ursache. Die Folge: Er kann jetzt nicht schlafen.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'obwohl would be a contrast, falls a condition, damit a purpose — none of those fit here.', 'obwohl wäre ein Gegensatz, falls eine Bedingung, damit ein Zweck. Keins davon passt hier.', 'sodass and so … dass: Expressing Result'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ffa277b8-4967-5650-bf96-cd4e7228bd18'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1a2cb652-ff46-56bb-ba98-f6bbac567a13'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / bleiben / zu Hause / obwohl / es / regnen]', 'Write the sentence: I stay home although it''s raining. (main clause first; start with Ich)', NULL, 'Ich bleibe zu Hause, obwohl es regnet.', '["Ich bleibe zu Hause, obwohl es regnet.","Ich bleibe zu Hause, obwohl es regnet"]'::jsonb, 'Main clause first uses normal word order; the obwohl-clause follows with the verb at the end.', 'Hauptsatz zuerst: normale Wortstellung. Der obwohl-Satz folgt danach mit Verb am Ende.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'regnet stands at the end of the subordinate clause.', 'regnet steht am Ende des Nebensatzes.', 'obwohl: Expressing Contrast'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1a2cb652-ff46-56bb-ba98-f6bbac567a13'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ac6e8e0b-9c93-5d11-9f56-da1fc2f43476'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [obwohl / es / regnen / ich / bleiben / zu Hause]', 'Write the sentence: Although it''s raining, I stay home. (subordinate clause first; start with Obwohl)', NULL, 'Obwohl es regnet, bleibe ich zu Hause.', '["Obwohl es regnet, bleibe ich zu Hause.","Obwohl es regnet, bleibe ich zu Hause"]'::jsonb, 'Subordinate clause first: after the comma the verb bleibe comes first, then ich.', 'Nebensatz zuerst: Nach dem Komma steht zuerst das Verb bleibe, dann ich.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'This is the inversion: verb before subject right after the comma.', 'Das ist die Inversion: Verb vor Subjekt nach dem Komma.', 'obwohl: Expressing Contrast'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ac6e8e0b-9c93-5d11-9f56-da1fc2f43476'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1b3c5b19-84ba-5510-956a-b798cbd9d51d'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Chefin / schicken / eine E-Mail / damit / die Mitarbeiter / Bescheid wissen]', 'Write the sentence: The boss sends an email so that the employees know. (different subjects; start with Die Chefin)', NULL, 'Die Chefin schickt eine E-Mail, damit die Mitarbeiter Bescheid wissen.', '["Die Chefin schickt eine E-Mail, damit die Mitarbeiter Bescheid wissen.","Die Chefin schickt eine E-Mail, damit die Mitarbeiter Bescheid wissen"]'::jsonb, 'The boss sends, the employees know — different subjects, so damit is correct.', 'Die Chefin schickt, die Mitarbeiter wissen. Verschiedene Subjekte, deshalb damit.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'wissen stands at the end of the damit-clause.', 'wissen steht am Ende des damit-Satzes.', 'damit vs. um … zu: Same or Different Subject?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1b3c5b19-84ba-5510-956a-b798cbd9d51d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'eca34f1e-1e1f-5c0a-88a5-84db824178ec'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / lernen / jeden Tag / um / die Prüfung / bestehen]', 'Write the sentence: I study every day in order to pass the exam. (same subject; start with Ich; add zu before bestehen)', NULL, 'Ich lerne jeden Tag, um die Prüfung zu bestehen.', '["Ich lerne jeden Tag, um die Prüfung zu bestehen.","Ich lerne jeden Tag, um die Prüfung zu bestehen"]'::jsonb, 'Same subject (I study, I pass) — so um … zu is correct, not damit.', 'Gleiches Subjekt (ich lerne, ich bestehe). Deshalb um ... zu, nicht damit.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'zu goes directly before the infinitive bestehen.', 'zu steht direkt vor dem Infinitiv bestehen.', 'damit vs. um … zu: Same or Different Subject?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'eca34f1e-1e1f-5c0a-88a5-84db824178ec'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b45df796-8aa2-59ed-ada0-e0b6a7a32220'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Chef / erklären / die Regeln / damit / die neuen Mitarbeiter / keine Fehler machen]', 'Write the sentence: The boss explains the rules so that the new employees don''t make mistakes. (different subjects; start with Der Chef)', NULL, 'Der Chef erklärt die Regeln, damit die neuen Mitarbeiter keine Fehler machen.', '["Der Chef erklärt die Regeln, damit die neuen Mitarbeiter keine Fehler machen.","Der Chef erklärt die Regeln, damit die neuen Mitarbeiter keine Fehler machen"]'::jsonb, 'The boss explains, the employees make no mistakes — different subjects, so damit is correct.', 'Der Chef erklärt, die Mitarbeiter machen keine Fehler. Verschiedene Subjekte, deshalb damit.', NULL, 5, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'machen stands at the end of the damit-clause.', 'machen steht am Ende des damit-Satzes.', 'damit vs. um … zu: Same or Different Subject?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b45df796-8aa2-59ed-ada0-e0b6a7a32220'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'afaeb9d0-26ed-58b4-8f30-827964163fb7'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Nachbar / hören / seine Musik / sehr laut / sodass / ich nicht schlafen können]', 'Write the sentence: The neighbor plays his music very loudly, so I can''t sleep. (start with Der Nachbar)', NULL, 'Der Nachbar hört seine Musik sehr laut, sodass ich nicht schlafen kann.', '["Der Nachbar hört seine Musik sehr laut, sodass ich nicht schlafen kann.","Der Nachbar hört seine Musik sehr laut, sodass ich nicht schlafen kann","Der Nachbar hört seine Musik sehr laut, so dass ich nicht schlafen kann.","Der Nachbar hört seine Musik sehr laut, so dass ich nicht schlafen kann"]'::jsonb, 'sodass states the result: the neighbor is loud, so I can''t sleep.', 'sodass nennt die Folge: Der Nachbar ist laut, deshalb kann ich nicht schlafen.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'kann stands at the end of the sodass-clause.', 'kann steht am Ende des sodass-Satzes.', 'sodass and so … dass: Expressing Result'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'afaeb9d0-26ed-58b4-8f30-827964163fb7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '69660127-dad4-5923-a463-4417d404b001'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [das Formular / sein / so kompliziert / dass / ich / Hilfe brauchen]', 'Write the sentence: The form is so complicated that I need help. (start with Das Formular)', NULL, 'Das Formular ist so kompliziert, dass ich Hilfe brauche.', '["Das Formular ist so kompliziert, dass ich Hilfe brauche.","Das Formular ist so kompliziert, dass ich Hilfe brauche"]'::jsonb, 'so kompliziert emphasizes the adjective; dass introduces the result.', 'so kompliziert betont das Adjektiv, dass leitet die Folge ein.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'brauche stands at the end, with Hilfe right before it.', 'brauche steht am Ende, Hilfe davor.', 'sodass and so … dass: Expressing Result'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '69660127-dad4-5923-a463-4417d404b001'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2f40a328-0bd6-50d4-ad70-e8aa521d7d42'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [falls / du / Hilfe / brauchen / ich / dir gern helfen]', 'Write the sentence: If you need help, I''ll gladly help you. (subordinate clause first; start with Falls)', NULL, 'Falls du Hilfe brauchst, helfe ich dir gern.', '["Falls du Hilfe brauchst, helfe ich dir gern.","Falls du Hilfe brauchst, helfe ich dir gern"]'::jsonb, 'Subordinate clause first: after the comma the verb helfe comes first.', 'Nebensatz zuerst: Nach dem Komma steht zuerst das Verb helfe.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'brauchst stands at the end of the falls-clause.', 'brauchst steht am Ende des falls-Satzes.', 'falls: Expressing a Condition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2f40a328-0bd6-50d4-ad70-e8aa521d7d42'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ca238aa0-5569-5578-8afb-d1e192ebcd25'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / anrufen dich / falls / ich / Hilfe / brauchen]', 'Write the sentence: I''ll call you if I need help. (main clause first; start with Ich)', NULL, 'Ich rufe dich an, falls ich Hilfe brauche.', '["Ich rufe dich an, falls ich Hilfe brauche.","Ich rufe dich an, falls ich Hilfe brauche"]'::jsonb, 'Main clause first uses normal word order, followed by the falls-clause.', 'Hauptsatz zuerst: normale Wortstellung, dann der falls-Satz.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'brauche stands at the end of the falls-clause.', 'brauche steht am Ende des falls-Satzes.', 'falls: Expressing a Condition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ca238aa0-5569-5578-8afb-d1e192ebcd25'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '08f3258b-002f-54d2-9221-fbfca4c6fd5a'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / arbeiten / weiter / obwohl / er / müde / sein]', 'Write the sentence: He keeps working although he''s tired. (start with Er)', NULL, 'Er arbeitet weiter, obwohl er müde ist.', '["Er arbeitet weiter, obwohl er müde ist.","Er arbeitet weiter, obwohl er müde ist"]'::jsonb, 'obwohl introduces the contrast: being tired but working anyway.', 'obwohl leitet den Gegensatz ein: müde sein, aber trotzdem arbeiten.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ist stands at the end of the obwohl-clause.', 'ist steht am Ende des obwohl-Satzes.', 'obwohl: Expressing Contrast'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '08f3258b-002f-54d2-9221-fbfca4c6fd5a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7bef145b-7118-531b-a8fb-1c3819555d80'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'error_correction', 'Finde den Fehler: Sie hat viel gelernt sodass sie die Prüfung bestanden hat.', 'Correct the punctuation: a comma always comes before sodass. (She studied a lot, so she passed the exam.)', NULL, 'Sie hat viel gelernt, sodass sie die Prüfung bestanden hat.', '["Sie hat viel gelernt, sodass sie die Prüfung bestanden hat.","Sie hat viel gelernt, sodass sie die Prüfung bestanden hat","Sie hat viel gelernt, so dass sie die Prüfung bestanden hat.","Sie hat viel gelernt, so dass sie die Prüfung bestanden hat"]'::jsonb, 'A comma always comes before sodass, like before any other Nebensatz.', 'Vor sodass steht immer ein Komma, wie vor jedem Nebensatz.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only the comma was missing; the word order was already correct.', 'Nur das Komma hat gefehlt, die Wortstellung war schon richtig.', 'Five Mistakes to Avoid'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7bef145b-7118-531b-a8fb-1c3819555d80'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '39113bce-095f-568a-bb42-9609c4c6f399'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'error_correction', 'Finde den Fehler: Damit meine Kinder Deutsch lernen, ich sehe jeden Tag einen Film mit ihnen.', 'Correct the word order in the main clause. (So that my children learn German, I watch a film with them every day.)', NULL, 'Damit meine Kinder Deutsch lernen, sehe ich jeden Tag einen Film mit ihnen.', '["Damit meine Kinder Deutsch lernen, sehe ich jeden Tag einen Film mit ihnen.","Damit meine Kinder Deutsch lernen, sehe ich jeden Tag einen Film mit ihnen"]'::jsonb, 'After the damit-clause, the main clause starts with the verb, then the subject.', 'Nach dem Nebensatz mit damit steht im Hauptsatz zuerst das Verb, dann das Subjekt.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sehe stands right after the comma, with ich after it.', 'sehe steht direkt nach dem Komma, ich danach.', 'Five Mistakes to Avoid'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '39113bce-095f-568a-bb42-9609c4c6f399'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f6bc86f0-fd9a-5df4-88e1-044f746c18a7'::uuid, 'c003e196-0e8e-5689-b411-e5b3f2d562c9'::uuid, 5, 'multiple_choice', 'Du bist im Bewerbungsgespräch. Was sagst du höflich und richtig?', 'You''re in a job interview. What''s the polite and correct thing to say? (If you have questions, you can call me.)', '["Falls Sie Fragen haben, können Sie mich gern anrufen.","Falls Sie Fragen haben, Sie können mich gern anrufen.","Sie können mich gern anrufen falls Sie Fragen haben.","Ob Sie Fragen haben, können Sie mich gern anrufen."]'::jsonb, 'Falls Sie Fragen haben, können Sie mich gern anrufen.', NULL, 'Subordinate clause first: after the comma the verb können comes before Sie.', 'Nebensatz zuerst: Nach dem Komma steht das Verb können vor Sie.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options lack inversion, drop the comma, or use the wrong connector ob.', 'Die anderen Optionen haben keine Inversion, kein Komma oder den falschen Konnektor ob.', 'falls: Expressing a Condition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f6bc86f0-fd9a-5df4-88e1-044f746c18a7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '44fd66bf-f36e-51ec-82c5-850e2220d0a1'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Ich habe Kopfschmerzen. ___ nehme ich eine Tablette.', 'Fill in the connector (reason → result, position 1): I have a headache. That''s why I''m taking a tablet. Use deshalb.', NULL, 'Deshalb', '["Deshalb","deshalb"]'::jsonb, 'deshalb takes position 1; the verb nehme follows immediately.', 'deshalb steht auf Position 1, das Verb nehme folgt direkt danach.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'deshalb is the standard word for a reason-to-result connection at the start of a sentence.', 'deshalb ist das Standardwort, um einen Grund mit einer Folge zu verbinden — hier am Satzanfang.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '44fd66bf-f36e-51ec-82c5-850e2220d0a1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e68cc218-5cdb-5080-8ccf-3ea909d4ef4f'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Der Kollege ist krank. ___ übernehme ich sein Projekt.', 'Fill in the connector (reason → result, position 1): The colleague is sick. That''s why I''m taking over his project. Use deswegen.', NULL, 'Deswegen', '["Deswegen","deswegen"]'::jsonb, 'deswegen means the same as deshalb; the verb follows right after it in position 2.', 'deswegen bedeutet dasselbe wie deshalb. Das Verb folgt direkt danach auf Position 2.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'deswegen is the connector explicitly requested here, and it fits the reason-to-result meaning.', 'deswegen ist hier ausdrücklich gefragt und passt zur Bedeutung Grund → Folge.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e68cc218-5cdb-5080-8ccf-3ea909d4ef4f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '472b462d-71c8-5178-92a4-6ee5892094c8'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Der Nachbar feiert jede Nacht laut. ___ beschwere ich mich beim Vermieter.', 'Fill in the connector (reason → result, position 1): The neighbor parties loudly every night. That''s why I''m complaining to the landlord. Use darum.', NULL, 'Darum', '["Darum","darum"]'::jsonb, 'darum is a third way to say deshalb; the verb beschwere follows right after it.', 'darum ist eine dritte Möglichkeit für deshalb. Das Verb beschwere steht direkt danach.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'darum was explicitly requested and expresses the same reason-to-result meaning as deshalb.', 'darum ist hier ausdrücklich gefragt und drückt dieselbe Bedeutung Grund → Folge wie deshalb aus.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '472b462d-71c8-5178-92a4-6ee5892094c8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd089233c-5df9-5f41-81fe-cea40d619806'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Die Prüfung ist schwer. Ich melde mich ___ an.', 'Fill in the connector mid-sentence (contrast): The exam is hard. I''m signing up anyway. Use trotzdem, right after mich.', NULL, 'trotzdem', '["trotzdem"]'::jsonb, 'trotzdem sits mid-sentence here; the verb melde already stands in position 2.', 'trotzdem steht hier mitten im Satz; das Verb melde steht schon auf Position 2.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'trotzdem is the only connector that fits a contrast (hard exam, but signing up anyway) in this exact position.', 'trotzdem ist der einzige Konnektor, der hier zum Gegensatz (schwere Prüfung, trotzdem Anmeldung) passt.', 'Position 1 or Mid-Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd089233c-5df9-5f41-81fe-cea40d619806'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '525e8240-3a6a-5fda-b92f-aea179a7e6c9'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Das Hotel ist teuer. Es liegt ___ weit vom Strand entfernt.', 'Fill in the connector mid-sentence (additional argument): The hotel is expensive. It''s also located far from the beach. Use außerdem, right after liegt.', NULL, 'außerdem', '["außerdem"]'::jsonb, 'außerdem sits mid-sentence, right after the verb liegt, adding one more argument.', 'außerdem steht hier mitten im Satz, direkt nach dem Verb liegt, und fügt ein weiteres Argument hinzu.', NULL, 5, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'außerdem is the connector for adding a second, independent argument, exactly the job this sentence needs.', 'außerdem ist der Konnektor, um ein zweites, unabhängiges Argument hinzuzufügen — genau das braucht dieser Satz.', 'Position 1 or Mid-Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '525e8240-3a6a-5fda-b92f-aea179a7e6c9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '848fc793-cfe9-597d-b97e-1b75c96d43e2'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Bring deinen Ausweis mit. ___ kannst du das Formular nicht abgeben.', 'Fill in the connector (negative consequence, position 1): Bring your ID. Otherwise you can''t hand in the form. Use sonst.', NULL, 'Sonst', '["Sonst","sonst"]'::jsonb, 'sonst names the negative consequence of not bringing the ID.', 'sonst nennt die negative Folge, wenn man den Ausweis nicht mitbringt.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sonst is the only connector that expresses ''otherwise, or else'' after an instruction.', 'sonst ist der einzige Konnektor, der ''andernfalls'' nach einer Anweisung ausdrückt.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '848fc793-cfe9-597d-b97e-1b75c96d43e2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8e22ba42-e8f3-5d34-88e5-1bc0a3f9a86d'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Wir schmücken zuerst den Raum. ___ backen wir den Kuchen.', 'Fill in the connector (temporal sequence, position 1): First we decorate the room. Then we bake the cake. Use dann.', NULL, 'Dann', '["Dann","dann"]'::jsonb, 'dann shows the next step in the sequence; the verb backen follows in position 2.', 'dann zeigt den nächsten Schritt. Das Verb backen folgt auf Position 2.', NULL, 7, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'dann is the standard word for the next step in a simple sequence of actions.', 'dann ist das Standardwort für den nächsten Schritt in einer einfachen Handlungsfolge.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8e22ba42-e8f3-5d34-88e5-1bc0a3f9a86d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0b4c0ae4-b72e-5175-9631-63d2f91f8e8a'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Ich fülle das Formular beim Arzt aus. ___ warte ich im Wartezimmer.', 'Fill in the connector (temporal sequence, position 1): I fill out the form at the doctor''s. After that I wait in the waiting room. Use danach.', NULL, 'Danach', '["Danach","danach"]'::jsonb, 'danach marks the next step; the verb warte follows in position 2.', 'danach markiert den nächsten Schritt. Das Verb warte folgt auf Position 2.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'danach fits the meaning ''after that step'' better than dann, which is more general.', 'danach passt zur Bedeutung ''nach diesem Schritt'' besser als das allgemeinere dann.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0b4c0ae4-b72e-5175-9631-63d2f91f8e8a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7269ff1b-c460-5931-b727-81edb7e34dd3'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Er lernt jeden Abend. ___ trinkt er viel Kaffee.', 'Fill in the connector (simultaneous action, position 1): He studies every evening. While doing so, he drinks a lot of coffee. Use dabei.', NULL, 'Dabei', '["Dabei","dabei"]'::jsonb, 'dabei stands in position 1 here, referring back to the action in the first sentence.', 'dabei steht hier auf Position 1 und bezieht sich auf die Handlung im ersten Satz.', NULL, 9, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'dabei is the only connector that expresses ''while doing that'', referring back to the previous action.', 'dabei ist der einzige Konnektor, der ''währenddessen'' als Bezug auf die vorherige Handlung ausdrückt.', 'Position 1 or Mid-Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7269ff1b-c460-5931-b727-81edb7e34dd3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9582522f-29a9-5771-b5f7-20bcf07937cc'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'fill_blank', 'Meine Schwester liest gern Bücher. ___ sieht mein Bruder lieber fern.', 'Fill in the connector (contrast between two people, position 1): My sister likes reading books. My brother, in contrast, prefers watching TV. Use dagegen.', NULL, 'Dagegen', '["Dagegen","dagegen"]'::jsonb, 'dagegen contrasts the brother''s preference with the sister''s.', 'dagegen stellt die Vorliebe des Bruders der Schwester gegenüber.', NULL, 10, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'dagegen is the connector for contrasting two different people or things, not just one situation.', 'dagegen ist der Konnektor für den Gegensatz zwischen zwei Personen oder Dingen, nicht nur einer Situation.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9582522f-29a9-5771-b5f7-20bcf07937cc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '08ac94c8-5290-5c4c-ae37-77a90a52a4a9'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'error_correction', 'Finde den Fehler: Es schneit stark. Deshalb ich bleibe zu Hause.', 'Fix the word order after deshalb: It''s snowing hard. That''s why I''m staying home.', NULL, 'Es schneit stark. Deshalb bleibe ich zu Hause.', '["Es schneit stark. Deshalb bleibe ich zu Hause.","Es schneit stark. Deshalb bleibe ich zu Hause","Es schneit stark, deshalb bleibe ich zu Hause.","Es schneit stark, deshalb bleibe ich zu Hause"]'::jsonb, 'The verb bleibe belongs right after deshalb, not the subject ich.', 'Das Verb bleibe gehört direkt nach deshalb, nicht das Subjekt ich.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'deshalb occupies position 1, so the verb must be the very next word, in position 2.', 'deshalb besetzt Position 1. Also muss das Verb direkt danach stehen.', 'Five Mistakes to Avoid'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '08ac94c8-5290-5c4c-ae37-77a90a52a4a9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '75073449-1179-51a4-8e83-99d340c64710'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'error_correction', 'Finde den Fehler: Ich bin erkältet, trotzdem ich gehe schwimmen.', 'Fix the word order after trotzdem: I have a cold, but I''m going swimming anyway.', NULL, 'Ich bin erkältet, trotzdem gehe ich schwimmen.', '["Ich bin erkältet, trotzdem gehe ich schwimmen.","Ich bin erkältet, trotzdem gehe ich schwimmen","Ich bin erkältet. Trotzdem gehe ich schwimmen.","Ich bin erkältet. Trotzdem gehe ich schwimmen"]'::jsonb, 'trotzdem is not a subordinator, so the verb gehe must follow it directly, not the subject.', 'trotzdem ist kein Nebensatz-Konnektor. Das Verb gehe muss direkt danach stehen, nicht das Subjekt.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Like obwohl, trotzdem marks a contrast, but unlike obwohl it starts a main clause with verb-second order.', 'Wie obwohl markiert trotzdem einen Gegensatz, aber anders als obwohl beginnt es einen Hauptsatz mit Verb auf Position 2.', 'Five Mistakes to Avoid'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '75073449-1179-51a4-8e83-99d340c64710'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7b1b6c9b-4785-5ab5-89dd-6563796c3726'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 4, 'multiple_choice', 'Welcher zweite Satz ist richtig? Der Aufzug ist kaputt.', 'Choose the correct second sentence: The elevator is broken. That''s why we''re taking the stairs.', '["Deshalb nehmen wir die Treppe.","Deshalb wir nehmen die Treppe.","Obwohl nehmen wir die Treppe.","Deshalb, nehmen wir die Treppe."]'::jsonb, 'Deshalb nehmen wir die Treppe.', NULL, 'Deshalb takes position 1, the verb nehmen follows directly, and no comma is needed after the connector.', 'Deshalb steht auf Position 1, das Verb nehmen folgt direkt danach, kein Komma nötig.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options put the subject before the verb, use obwohl (a subordinator) as if it were deshalb, or add a wrong comma.', 'Die anderen Sätze stellen das Subjekt vor das Verb, benutzen obwohl (einen Nebensatz-Konnektor) wie deshalb, oder setzen ein falsches Komma.', 'Position 1 or Mid-Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7b1b6c9b-4785-5ab5-89dd-6563796c3726'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '94c1ea1c-f5ac-527f-b684-2d2d2c933698'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib die Sätze: [ich / Fieber / haben / deshalb / ich / zum Arzt / gehen]', 'Write two sentences: I have a fever. That''s why I''m going to the doctor. (Präsens; start the second sentence with Deshalb)', NULL, 'Ich habe Fieber. Deshalb gehe ich zum Arzt.', '["Ich habe Fieber. Deshalb gehe ich zum Arzt.","Ich habe Fieber. Deshalb gehe ich zum Arzt","Ich habe Fieber, deshalb gehe ich zum Arzt.","Ich habe Fieber, deshalb gehe ich zum Arzt"]'::jsonb, 'deshalb opens the second sentence and the verb gehe follows in position 2.', 'deshalb eröffnet den zweiten Satz, das Verb gehe folgt auf Position 2.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The reason (fever) and the result (going to the doctor) connect naturally with deshalb in position 1.', 'Der Grund (Fieber) und die Folge (zum Arzt gehen) verbindet man natürlich mit deshalb auf Position 1.', 'How to Build the Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '94c1ea1c-f5ac-527f-b684-2d2d2c933698'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'cf846c88-59b8-589c-9e02-0e4a599a6501'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib die Sätze: [ich / krank / sein / trotzdem / ich / arbeiten]', 'Write two sentences: I''m sick. Nevertheless, I''m working. (Präsens; start the second sentence with Trotzdem)', NULL, 'Ich bin krank. Trotzdem arbeite ich.', '["Ich bin krank. Trotzdem arbeite ich.","Ich bin krank. Trotzdem arbeite ich","Ich bin krank, trotzdem arbeite ich.","Ich bin krank, trotzdem arbeite ich"]'::jsonb, 'Trotzdem opens the second sentence; the verb arbeite follows right after it in position 2.', 'Trotzdem eröffnet den zweiten Satz; das Verb arbeite folgt direkt danach auf Position 2.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Trotzdem is the right choice because working despite being sick is a contrast, not a reason.', 'Trotzdem passt, weil es ein Gegensatz ist, trotz Krankheit zu arbeiten.', 'How to Build the Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'cf846c88-59b8-589c-9e02-0e4a599a6501'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9add58dd-cf60-5d7c-ae08-0b38296ce670'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib die Sätze: [wir / kein Geld / haben / darum / wir / nicht in Urlaub / fahren]', 'Write two sentences: We have no money. That''s why we''re not going on vacation. (Präsens; start the second sentence with Darum)', NULL, 'Wir haben kein Geld. Darum fahren wir nicht in Urlaub.', '["Wir haben kein Geld. Darum fahren wir nicht in Urlaub.","Wir haben kein Geld. Darum fahren wir nicht in Urlaub","Wir haben kein Geld, darum fahren wir nicht in Urlaub.","Wir haben kein Geld, darum fahren wir nicht in Urlaub"]'::jsonb, 'Darum opens the second sentence; the verb fahren follows in position 2, with nicht before the final phrase.', 'Darum eröffnet den zweiten Satz; das Verb fahren folgt auf Position 2. Das Wort nicht steht vor der letzten Wortgruppe.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'darum is one of the three synonyms for deshalb and fits this reason-to-result sentence.', 'darum ist eines der drei Synonyme für deshalb und passt zu diesem Grund-Folge-Satz.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9add58dd-cf60-5d7c-ae08-0b38296ce670'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9706b2f1-0a3f-5b6a-beba-c726636e08ec'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib die Sätze: [die Miete / hoch / sein / die Wohnung / sein / außerdem / laut]', 'Write two sentences: The rent is high. The apartment is also loud. (mid-sentence: put außerdem right after ist in the second sentence)', NULL, 'Die Miete ist hoch. Die Wohnung ist außerdem laut.', '["Die Miete ist hoch. Die Wohnung ist außerdem laut.","Die Miete ist hoch. Die Wohnung ist außerdem laut","Die Miete ist hoch, die Wohnung ist außerdem laut.","Die Miete ist hoch, die Wohnung ist außerdem laut"]'::jsonb, 'außerdem sits mid-sentence, right after ist, adding a second argument.', 'außerdem steht mitten im Satz, direkt nach ist, und fügt ein zweites Argument hinzu.', NULL, 4, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The mid-sentence position keeps die Wohnung in position 1 and außerdem right after the verb ist.', 'Die Position mitten im Satz lässt die Wohnung auf Position 1 und außerdem direkt nach dem Verb ist.', 'Position 1 or Mid-Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9706b2f1-0a3f-5b6a-beba-c726636e08ec'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '216d325c-ea52-5315-820f-8efe8c5c5b61'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib die Sätze: [beeilen / dich / sonst / du / den Zug / verpassen]', 'Write two sentences (imperative + warning): Hurry up. Otherwise you''ll miss the train. (start the second sentence with Sonst)', NULL, 'Beeil dich. Sonst verpasst du den Zug.', '["Beeil dich. Sonst verpasst du den Zug.","Beeil dich. Sonst verpasst du den Zug","Beeil dich, sonst verpasst du den Zug.","Beeil dich, sonst verpasst du den Zug","Beeil dich! Sonst verpasst du den Zug.","Beeil dich! Sonst verpasst du den Zug","Beeile dich. Sonst verpasst du den Zug.","Beeile dich. Sonst verpasst du den Zug","Beeile dich, sonst verpasst du den Zug.","Beeile dich, sonst verpasst du den Zug","Beeile dich! Sonst verpasst du den Zug.","Beeile dich! Sonst verpasst du den Zug","Beeil dich. Sonst verpasst du den Zug!","Beeil dich, sonst verpasst du den Zug!","Beeile dich. Sonst verpasst du den Zug!","Beeile dich, sonst verpasst du den Zug!"]'::jsonb, 'sonst opens the second sentence; the verb verpasst follows right after it, then the subject du.', 'sonst eröffnet den zweiten Satz; das Verb verpasst folgt direkt danach, dann das Subjekt du.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sonst names the negative consequence of not hurrying, exactly the warning function it has.', 'sonst nennt die negative Folge, wenn man sich nicht beeilt — genau seine Warnfunktion.', 'How to Build the Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '216d325c-ea52-5315-820f-8efe8c5c5b61'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5f27a055-73ec-5e65-a18a-f09816dc3eb7'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib die Sätze: [wir / zuerst / einkaufen gehen / dann / wir / kochen]', 'Write two sentences, in this exact order: first we go shopping, then we cook. (start the first sentence with Wir gehen zuerst; start the second sentence with Dann)', NULL, 'Wir gehen zuerst einkaufen. Dann kochen wir.', '["Wir gehen zuerst einkaufen. Dann kochen wir.","Wir gehen zuerst einkaufen. Dann kochen wir","Wir gehen zuerst einkaufen, dann kochen wir.","Wir gehen zuerst einkaufen, dann kochen wir"]'::jsonb, 'dann opens the second sentence; the verb kochen follows right after it, then the subject wir.', 'dann eröffnet den zweiten Satz; das Verb kochen folgt direkt danach, dann das Subjekt wir.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'dann marks the next step in a simple sequence of two actions.', 'dann markiert den nächsten Schritt in einer einfachen Handlungsfolge aus zwei Schritten.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5f27a055-73ec-5e65-a18a-f09816dc3eb7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'efafe2da-8a5c-52da-aa05-74e244fe1e13'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib die Sätze: [ich / duschen / danach / ich / frühstücken]', 'Write two sentences: I take a shower. After that I have breakfast. (start the second sentence with Danach)', NULL, 'Ich dusche. Danach frühstücke ich.', '["Ich dusche. Danach frühstücke ich.","Ich dusche. Danach frühstücke ich","Ich dusche, danach frühstücke ich.","Ich dusche, danach frühstücke ich","Ich dusche mich. Danach frühstücke ich.","Ich dusche mich. Danach frühstücke ich","Ich dusche mich, danach frühstücke ich.","Ich dusche mich, danach frühstücke ich"]'::jsonb, 'danach opens the second sentence; the verb frühstücke follows right after it, then the subject ich.', 'danach eröffnet den zweiten Satz; das Verb frühstücke folgt direkt danach, dann das Subjekt ich.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'danach fits a clear morning routine, one step following the other.', 'danach passt zu einer klaren Morgenroutine, ein Schritt nach dem anderen.', 'The Connectors at a Glance'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'efafe2da-8a5c-52da-aa05-74e244fe1e13'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '257e6e1f-6882-5eea-8388-852414828736'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib den Satz: [sie / joggen / und / hören / dabei / Musik]', 'Write one sentence: She jogs and listens to music while doing so. (dabei mid-sentence, right after hört)', NULL, 'Sie joggt und hört dabei Musik.', '["Sie joggt und hört dabei Musik.","Sie joggt und hört dabei Musik"]'::jsonb, 'dabei sits mid-sentence, right after the verb hört, linking the two simultaneous actions.', 'dabei steht mitten im Satz, direkt nach dem Verb hört, und verbindet die beiden gleichzeitigen Handlungen.', NULL, 8, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'dabei marks that listening to music happens at the same time as jogging.', 'dabei zeigt, dass das Musikhören gleichzeitig mit dem Joggen passiert.', 'Position 1 or Mid-Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '257e6e1f-6882-5eea-8388-852414828736'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '57e6719d-5d32-50af-95a3-20294da1432d'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'sentence_building', 'Schreib die Sätze: [mein Vater / gern kochen / dagegen / meine Mutter / gern backen]', 'Write two sentences: My father likes to cook. My mother, in contrast, likes to bake. (start the second sentence with Dagegen)', NULL, 'Mein Vater kocht gern. Dagegen backt meine Mutter gern.', '["Mein Vater kocht gern. Dagegen backt meine Mutter gern.","Mein Vater kocht gern. Dagegen backt meine Mutter gern","Mein Vater kocht gern, dagegen backt meine Mutter gern.","Mein Vater kocht gern, dagegen backt meine Mutter gern"]'::jsonb, 'Dagegen opens the second sentence; the verb backt follows right after it, then the subject meine Mutter.', 'Dagegen eröffnet den zweiten Satz; das Verb backt folgt direkt danach, dann das Subjekt meine Mutter.', NULL, 9, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'dagegen contrasts two different people''s preferences, exactly its function.', 'dagegen stellt die Vorlieben zweier verschiedener Personen gegenüber — genau seine Funktion.', 'Position 1 or Mid-Sentence'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '57e6719d-5d32-50af-95a3-20294da1432d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2350b7e7-3fc0-5834-bec3-8162b99c720f'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'error_correction', 'Finde den Fehler: Die Bibliothek schließt um 18 Uhr, deswegen sie muss jetzt gehen.', 'Fix the word order after deswegen: The library closes at 6pm, that''s why she has to leave now.', NULL, 'Die Bibliothek schließt um 18 Uhr, deswegen muss sie jetzt gehen.', '["Die Bibliothek schließt um 18 Uhr, deswegen muss sie jetzt gehen.","Die Bibliothek schließt um 18 Uhr, deswegen muss sie jetzt gehen","Die Bibliothek schließt um 18 Uhr. Deswegen muss sie jetzt gehen.","Die Bibliothek schließt um 18 Uhr. Deswegen muss sie jetzt gehen"]'::jsonb, 'The modal verb muss belongs right after deswegen, then the subject sie, then the infinitive gehen at the end.', 'Das Modalverb muss gehört direkt nach deswegen, dann das Subjekt sie, dann der Infinitiv gehen am Ende.', NULL, 10, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'deswegen sends the finite verb muss to position 2; sie moves after it, exactly as with any main-clause connector.', 'deswegen schickt das finite Verb muss auf Position 2; sie steht danach, genau wie bei jedem Hauptsatz-Konnektor.', 'Five Mistakes to Avoid'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2350b7e7-3fc0-5834-bec3-8162b99c720f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4c0e41d8-b6e4-5015-a145-8785c43536b4'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'error_correction', 'Finde den Fehler: Zieh dir eine Jacke an. Sonst du erkältest dich.', 'Fix the word order after sonst: Put on a jacket. Otherwise you''ll catch a cold.', NULL, 'Zieh dir eine Jacke an. Sonst erkältest du dich.', '["Zieh dir eine Jacke an. Sonst erkältest du dich.","Zieh dir eine Jacke an. Sonst erkältest du dich","Zieh dir eine Jacke an, sonst erkältest du dich.","Zieh dir eine Jacke an, sonst erkältest du dich"]'::jsonb, 'The verb erkältest belongs right after sonst, then the subject du, then the reflexive dich.', 'Das Verb erkältest gehört direkt nach sonst, dann das Subjekt du, dann das Reflexivpronomen dich.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sonst pushes the verb to position 2, exactly like deshalb, trotzdem and the other connectors.', 'sonst schickt das Verb auf Position 2, genau wie deshalb, trotzdem und die anderen Konnektoren.', 'Five Mistakes to Avoid'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4c0e41d8-b6e4-5015-a145-8785c43536b4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '910266a5-1a37-55e2-a32e-7a73d154c863'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'multiple_choice', 'Welcher Satz drückt den gleichen Gegensatz aus wie: Er geht raus, obwohl es regnet.?', 'Which sentence expresses the same contrast as: Er geht raus, obwohl es regnet. (He goes out although it''s raining.)', '["Es regnet. Trotzdem geht er raus.","Es regnet. Deshalb geht er raus.","Er geht raus, trotzdem es regnet.","Es regnet, obwohl er geht raus."]'::jsonb, 'Es regnet. Trotzdem geht er raus.', NULL, 'trotzdem starts its own main clause with verb-second order; obwohl starts a Nebensatz with the verb at the end — both express the same contrast.', 'trotzdem beginnt einen eigenen Hauptsatz mit Verb auf Position 2; obwohl beginnt einen Nebensatz mit Verb am Ende. Beide drücken denselben Gegensatz aus.', NULL, 12, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options change the meaning to a reason (deshalb), put trotzdem in verb-final order like obwohl, or reverse the clauses incorrectly with obwohl.', 'Die anderen Sätze ändern die Bedeutung zu einem Grund (deshalb) oder setzen trotzdem in Verbendstellung wie obwohl. Die letzte Option vertauscht die Sätze falsch mit obwohl.', 'Main-Clause Connector or Subordinator?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '910266a5-1a37-55e2-a32e-7a73d154c863'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3ea177b1-576c-5ec0-9ad8-03247e7a6ed3'::uuid, 'd123e21a-da34-5b37-8fc8-c5c703bf3d50'::uuid, 5, 'multiple_choice', 'Welcher Satz passt zur gleichen Idee wie: Ich lerne jeden Tag, damit ich die Prüfung bestehen kann.?', 'Which pair expresses the same idea as: Ich lerne jeden Tag, damit ich die Prüfung bestehen kann. (I study every day so that I can pass the exam.)', '["Ich möchte die Prüfung bestehen. Deshalb lerne ich jeden Tag.","Ich lerne jeden Tag. Deshalb ich bestehe die Prüfung.","Ich möchte die Prüfung bestehen, deshalb ich lerne jeden Tag.","Ich lerne jeden Tag, trotzdem bestehe ich die Prüfung."]'::jsonb, 'Ich möchte die Prüfung bestehen. Deshalb lerne ich jeden Tag.', NULL, 'damit introduces a purpose clause here: the Nebensatz states the goal. To express the same idea with deshalb, you state the goal first, then the action.', 'damit leitet hier einen Nebensatz ein, der den Zweck nennt. Für dieselbe Idee mit deshalb nennst du zuerst das Ziel, dann die Handlung.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Options 2 and 3 put the subject before the verb after deshalb; option 4 swaps in trotzdem, which changes the meaning to a contrast.', 'Die anderen Sätze stellen das Subjekt vor das Verb nach deshalb, in Option 2 und Option 3. Die letzte Option setzt trotzdem ein und ändert die Bedeutung zu einem Gegensatz.', 'Main-Clause Connector or Subordinator?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3ea177b1-576c-5ec0-9ad8-03247e7a6ed3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2774f625-5720-5876-9ade-5093c3b64274'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'fill_blank', 'Am Wochenende will ich entweder lesen ___ schlafen.', 'Fill in the second connector: On the weekend I want to either read or sleep.', NULL, 'oder', '["oder"]'::jsonb, 'Here entweder … oder connects two verbs (infinitives) after will.', 'entweder … oder verbindet hier zwei Verben (Infinitive) nach will.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'oder always follows entweder — never und or aber.', 'Nach entweder kommt immer „oder“, nie „und“ oder „aber“.', 'How to Join Two Words or Phrases'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2774f625-5720-5876-9ade-5093c3b64274'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '13d9335f-dd05-5b53-8caf-c61b03adb6a7'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'fill_blank', 'Ich trinke weder Kaffee ___ Tee.', 'Fill in the second connector: I drink neither coffee nor tea.', NULL, 'noch', '["noch"]'::jsonb, 'noch always follows weder, never oder.', 'Nach weder folgt immer noch, nie oder.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'weder … noch negates two nouns together.', 'weder … noch verneint zwei Nomen zusammen.', 'The Five Connector Pairs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '13d9335f-dd05-5b53-8caf-c61b03adb6a7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '152ff07f-c836-55eb-bf00-3c7f063cbd27'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'fill_blank', 'Sowohl meine Schwester ___ auch mein Bruder wohnen in Berlin.', 'Fill in the missing word: Both my sister and my brother live in Berlin.', NULL, 'als', '["als","wie"]'::jsonb, 'als (or wie) belongs fixed to sowohl … auch; both are standard German.', 'als oder wie gehört fest zu sowohl … auch. Beide Formen sind korrekt.', NULL, 3, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'sowohl … als auch and sowohl … wie auch are both standard fixed pairs.', 'sowohl … als auch und sowohl … wie auch sind beide feste, korrekte Paare.', 'The Five Connector Pairs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '152ff07f-c836-55eb-bf00-3c7f063cbd27'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '59093fa1-35d8-5c10-bfbc-27264a650c9c'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'fill_blank', 'Er ist nicht nur pünktlich, ___ auch freundlich.', 'Fill in the connector: He is not only punctual, but also friendly.', NULL, 'sondern', '["sondern"]'::jsonb, 'sondern auch follows nicht nur; aber alone is wrong here.', 'Nach nicht nur folgt „sondern auch“, nie nur „aber“.', NULL, 4, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'sondern connects the second piece of information together with auch.', 'sondern verbindet die zweite Information mit auch.', 'The Five Connector Pairs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '59093fa1-35d8-5c10-bfbc-27264a650c9c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'efca8d67-9e64-51e5-bea7-f8d2e802c382'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'fill_blank', 'Die Wohnung ist zwar klein, ___ sie ist zentral.', 'Fill in the connector: The apartment is admittedly small, but it''s central.', NULL, 'aber', '["aber","doch"]'::jsonb, 'zwar announces a contrast; the contrast is usually introduced by aber, sometimes by doch.', 'zwar kündigt einen Gegensatz an. Der Gegensatz kommt meist mit aber, manchmal mit doch.', NULL, 5, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'aber (or doch) is a fixed partner of zwar.', 'aber (oder doch) ist ein fester Partner von zwar.', 'The Five Connector Pairs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'efca8d67-9e64-51e5-bea7-f8d2e802c382'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '843f4a9e-155f-5e30-a855-8cf96b029594'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'multiple_choice', 'Wähle den richtigen Konnektor: Wir fahren ___ mit dem Auto oder mit dem Zug.', 'Choose the correct connector: We''re traveling either by car or by train.', '["entweder","sowohl","weder","nicht nur"]'::jsonb, 'entweder', NULL, 'Only entweder pairs with oder; the other options need a different partner.', 'Nur entweder passt zu oder. Die anderen brauchen einen anderen Partner.', NULL, 6, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'sowohl needs als auch, weder needs noch, nicht nur needs sondern auch.', 'sowohl braucht als auch, weder braucht noch, nicht nur braucht sondern auch.', 'The Five Connector Pairs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '843f4a9e-155f-5e30-a855-8cf96b029594'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bc18ead7-79bb-5fd2-9b62-91ae6544d039'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'multiple_choice', 'Welcher Satz hat die richtige Wortstellung?', 'Which sentence is correct? (entweder … oder, with entweder opening the sentence and inversion)', '["Entweder bleibst du hier, oder du kommst mit.","Entweder bleibst du hier, aber du kommst mit.","Entweder bleibst du hier, oder kommst du mit.","Bleibst entweder du hier, oder du kommst mit."]'::jsonb, 'Entweder bleibst du hier, oder du kommst mit.', NULL, 'entweder occupies position one, so the verb bleibst follows right after; the second clause needs oder, not aber.', 'entweder steht auf Position eins, deshalb steht das Verb bleibst direkt danach; der zweite Teil braucht oder, nicht aber.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'entweder always pairs with oder, never aber; after oder the normal order returns.', 'entweder passt immer zu oder, nie zu aber; nach oder bleibt die normale Wortstellung.', 'Word Order: Joining Two Full Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bc18ead7-79bb-5fd2-9b62-91ae6544d039'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c5350a0c-c1ac-5655-956e-a9470a3e47be'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'multiple_choice', 'Was ist richtig?', 'Choose the correct sentence: I eat neither meat nor fish.', '["Ich esse weder Fleisch noch Fisch.","Ich esse weder Fleisch oder Fisch.","Ich esse nicht weder Fleisch noch Fisch.","Ich esse weder Fleisch, aber Fisch."]'::jsonb, 'Ich esse weder Fleisch noch Fisch.', NULL, 'noch always follows weder, no other word is possible.', 'Nach weder kommt immer noch, kein anderes Wort.', NULL, 8, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other sentences use oder, nicht, or aber instead of noch.', 'Die anderen Sätze benutzen „oder“, „nicht“ oder „aber“ statt „noch“.', 'Common Mistakes with Two-Part Connectors'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c5350a0c-c1ac-5655-956e-a9470a3e47be'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'dc94ed19-a63b-548b-b046-c1ec300ca545'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'fill_blank', 'Sie spricht nicht nur Deutsch, sondern ___ Englisch.', 'Fill in the missing word: She speaks not only German, but also English.', NULL, 'auch', '["auch"]'::jsonb, 'auch belongs fixed to sondern here, since Deutsch and Englisch are two equally weighted skills.', 'Bei zwei gleichwertigen Informationen gehört auch fest zu sondern.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Without auch, the second half of the connector is missing.', 'Ohne auch fehlt die zweite Hälfte des Konnektors.', 'Common Mistakes with Two-Part Connectors'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dc94ed19-a63b-548b-b046-c1ec300ca545'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2b373575-5952-55c3-aaf6-26b15a5603b8'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'fill_blank', 'Zwar ___ es heute kalt, aber wir gehen spazieren. (sein, Präsens, es)', 'Fill in the verb right after zwar (present tense of sein): Admittedly it''s cold today, but we''re going for a walk.', NULL, 'ist', '["ist"]'::jsonb, 'zwar sits in position one, so the verb ist follows immediately.', 'zwar steht auf Position eins, deshalb kommt das Verb ist direkt danach.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The subject es only follows after the verb.', 'Das Subjekt es folgt erst nach dem Verb.', 'Word Order: Joining Two Full Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2b373575-5952-55c3-aaf6-26b15a5603b8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6f8f04e8-834c-5084-9de7-f9161f8f9e10'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'error_correction', 'Finde den Fehler: Entweder wir bleiben zu Hause, oder gehen wir ins Kino.', 'Fix the word order: oder is a plain conjunction and never triggers inversion.', NULL, 'Entweder wir bleiben zu Hause, oder wir gehen ins Kino.', '["Entweder wir bleiben zu Hause, oder wir gehen ins Kino.","Entweder wir bleiben zu Hause, oder wir gehen ins Kino","Entweder bleiben wir zu Hause, oder wir gehen ins Kino.","Entweder bleiben wir zu Hause, oder wir gehen ins Kino","Entweder wir bleiben zu Hause oder wir gehen ins Kino.","Entweder wir bleiben zu Hause oder wir gehen ins Kino","Entweder bleiben wir zu Hause oder wir gehen ins Kino.","Entweder bleiben wir zu Hause oder wir gehen ins Kino"]'::jsonb, 'oder never pushes the verb before the subject; the second clause keeps normal order (wir gehen).', 'oder schiebt das Verb nie vor das Subjekt; der zweite Teil bleibt normal (wir gehen).', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'entweder itself allows either order (with or without inversion); only the oder-clause was actually wrong.', 'entweder erlaubt beide Reihenfolgen (mit oder ohne Inversion); nur der oder-Teil war falsch.', 'Word Order: Joining Two Full Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6f8f04e8-834c-5084-9de7-f9161f8f9e10'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7b041382-d2c2-5c76-871d-cb82019caeed'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'error_correction', 'Finde den Fehler: Er mag weder Fußball oder Tennis.', 'Fix the mistake: the second part of weder is never oder.', NULL, 'Er mag weder Fußball noch Tennis.', '["Er mag weder Fußball noch Tennis.","Er mag weder Fußball noch Tennis"]'::jsonb, 'weder always needs noch as its partner, never oder.', 'weder braucht immer noch als Partner, nie oder.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'noch negates the second noun together with weder.', 'noch verneint das zweite Nomen zusammen mit weder.', 'Common Mistakes with Two-Part Connectors'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7b041382-d2c2-5c76-871d-cb82019caeed'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '28d4709a-526c-5737-af2e-244cbe68f6b1'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 4, 'multiple_choice', 'Der Chef ist sowohl streng ___ auch fair. Wähle das richtige Wort.', 'Choose the correct word: The boss is both strict and fair.', '["als","sowie","und","oder"]'::jsonb, 'als', NULL, 'sowohl needs als auch (or wie auch) as its fixed partner.', 'sowohl braucht als auch (oder wie auch) als festen Partner.', NULL, 13, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'sowie, und, and oder do not pair with sowohl.', '„sowie“, „und“ und „oder“ passen nicht zu sowohl.', 'The Five Connector Pairs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '28d4709a-526c-5737-af2e-244cbe68f6b1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e5e06f48-f385-50b0-8dec-845e57088050'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'sentence_building', 'Schreib den Satz: [du / bleiben / heute / entweder / zu Hause / oder / du / gehen / ins Kino]', 'Write the sentence: Either you stay home today, or you go to the cinema. (start with Entweder; present tense; use the inverted order after Entweder)', NULL, 'Entweder bleibst du heute zu Hause, oder du gehst ins Kino.', '["Entweder bleibst du heute zu Hause, oder du gehst ins Kino.","Entweder bleibst du heute zu Hause, oder du gehst ins Kino","Entweder bleibst du heute zu Hause oder du gehst ins Kino.","Entweder bleibst du heute zu Hause oder du gehst ins Kino"]'::jsonb, 'entweder opens the sentence, so bleibst follows immediately; the comma before oder here is optional.', 'entweder eröffnet den Satz, deshalb steht bleibst direkt danach; das Komma vor oder ist hier optional.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'After oder the normal order returns: du before gehst.', 'Nach oder folgt die normale Wortstellung: du vor gehst.', 'Word Order: Joining Two Full Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e5e06f48-f385-50b0-8dec-845e57088050'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bb545565-dedf-57ee-aa72-002b7d0063cb'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Prüfung / sein / zwar / schwer / aber / ich / schaffen / sie]', 'Write the sentence: The exam is admittedly hard, but I''ll pass it. (zwar stands after the verb; present tense)', NULL, 'Die Prüfung ist zwar schwer, aber ich schaffe sie.', '["Die Prüfung ist zwar schwer, aber ich schaffe sie.","Die Prüfung ist zwar schwer, aber ich schaffe sie"]'::jsonb, 'Position one is already filled, so zwar stands after the verb ist.', 'Position eins ist schon besetzt, deshalb steht zwar nach dem Verb ist.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'aber introduces the contrast with normal word order.', 'aber führt den Gegensatz in normaler Wortstellung ein.', 'Word Order: Joining Two Full Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bb545565-dedf-57ee-aa72-002b7d0063cb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8861bbf0-8dfa-5511-b116-1ce132200ca3'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Arzt / empfehlen / nicht nur / mehr Sport / sondern auch / eine gesündere Ernährung]', 'Write the sentence: The doctor recommends not only more sport, but also a healthier diet. (conjugate empfehlen for er)', NULL, 'Der Arzt empfiehlt nicht nur mehr Sport, sondern auch eine gesündere Ernährung.', '["Der Arzt empfiehlt nicht nur mehr Sport, sondern auch eine gesündere Ernährung.","Der Arzt empfiehlt nicht nur mehr Sport, sondern auch eine gesündere Ernährung"]'::jsonb, 'empfehlen changes to empfiehlt (vowel shift e→ie).', 'empfehlen wird zu empfiehlt (Vokalwechsel e→ie).', NULL, 3, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'nicht nur and sondern auch stand directly before the two objects.', 'nicht nur und sondern auch stehen direkt vor den zwei Objekten.', 'How to Join Two Words or Phrases'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8861bbf0-8dfa-5511-b116-1ce132200ca3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c9ebf702-fd84-5864-a96e-13d430865304'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / mögen / sowohl / Tee / als auch / Kaffee]', 'Write the sentence: I like both tea and coffee. (conjugate mögen for ich)', NULL, 'Ich mag sowohl Tee als auch Kaffee.', '["Ich mag sowohl Tee als auch Kaffee.","Ich mag sowohl Tee als auch Kaffee"]'::jsonb, 'mögen becomes mag in the ich-form.', 'mögen wird zu mag in der ich-Form.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sowohl and als auch stand directly before the two objects.', 'sowohl und als auch stehen direkt vor den zwei Objekten.', 'How to Join Two Words or Phrases'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c9ebf702-fd84-5864-a96e-13d430865304'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '623bbf63-979c-5ca3-8174-1fd480494893'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Vermieter / erlauben / weder / Haustiere / noch / laute Partys]', 'Write the sentence: The landlord allows neither pets nor loud parties. (conjugate erlauben for er)', NULL, 'Der Vermieter erlaubt weder Haustiere noch laute Partys.', '["Der Vermieter erlaubt weder Haustiere noch laute Partys.","Der Vermieter erlaubt weder Haustiere noch laute Partys"]'::jsonb, 'weder and noch stand directly before the two objects.', 'weder und noch stehen direkt vor den zwei Objekten.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'erlaubt is the correct er-form of erlauben.', 'erlaubt ist die richtige er-Form von erlauben.', 'How to Join Two Words or Phrases'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '623bbf63-979c-5ca3-8174-1fd480494893'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '654ab89c-b528-5eec-a64f-6c1c1d95f7c7'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ihr / mitkommen / entweder / oder / ihr / hierbleiben]', 'Write the sentence: Either you (all) come along, or you stay here. (start with Entweder; use the inverted order after Entweder; separable verb mitkommen; present tense)', NULL, 'Entweder kommt ihr mit, oder ihr bleibt hier.', '["Entweder kommt ihr mit, oder ihr bleibt hier.","Entweder kommt ihr mit, oder ihr bleibt hier","Entweder kommt ihr mit oder ihr bleibt hier.","Entweder kommt ihr mit oder ihr bleibt hier"]'::jsonb, 'kommt stands in position two; the separable prefix mit moves to the end. The comma before oder here is optional.', 'kommt steht auf Position zwei, mit wandert ans Satzende. Das Komma vor oder ist hier optional.', NULL, 6, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'After oder the normal word order returns.', 'Nach oder folgt wieder die normale Wortstellung.', 'Word Order: Joining Two Full Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '654ab89c-b528-5eec-a64f-6c1c1d95f7c7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b633bd80-bd77-5d50-9e11-e899595d5384'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'error_correction', 'Finde den Fehler: Sowohl der Preis und das Design gefallen mir.', 'Fix the mistake: sowohl does not pair with und.', NULL, 'Sowohl der Preis als auch das Design gefallen mir.', '["Sowohl der Preis als auch das Design gefallen mir.","Sowohl der Preis als auch das Design gefallen mir"]'::jsonb, 'sowohl does not pair with und; its fixed partner is als auch (or wie auch).', 'sowohl passt nicht zu „und“. Der feste Partner ist „als auch“ (oder „wie auch“).', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sowohl … als auch forms the subject for gefallen here.', 'sowohl … als auch bildet hier das Subjekt für gefallen.', 'Common Mistakes with Two-Part Connectors'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b633bd80-bd77-5d50-9e11-e899595d5384'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd1f28035-a5fe-595c-a30a-36a541d4f8ac'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'error_correction', 'Finde den Fehler: Zwar ist das Zimmer laut aber es ist billig.', 'Fix the punctuation: a comma always comes before aber here.', NULL, 'Zwar ist das Zimmer laut, aber es ist billig.', '["Zwar ist das Zimmer laut, aber es ist billig.","Zwar ist das Zimmer laut, aber es ist billig"]'::jsonb, 'A comma always precedes aber when it joins two main clauses.', 'Vor aber steht immer ein Komma, wenn aber zwei Hauptsätze verbindet.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only the comma was missing; the word order was already correct.', 'Nur das Komma hat gefehlt, die Wortstellung war schon richtig.', 'Common Mistakes with Two-Part Connectors'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd1f28035-a5fe-595c-a30a-36a541d4f8ac'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7244dacf-0a98-5c9c-a387-fa7e57ee6e64'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'error_correction', 'Finde den Fehler: Er ist nicht nur müde, sondern hungrig auch.', 'Fix the word order: auch stands directly before hungrig, not after it.', NULL, 'Er ist nicht nur müde, sondern auch hungrig.', '["Er ist nicht nur müde, sondern auch hungrig.","Er ist nicht nur müde, sondern auch hungrig"]'::jsonb, 'auch stands directly before the second adjective, not after it.', 'auch steht direkt vor dem zweiten Adjektiv, nicht danach.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sondern auch stays together as a fixed unit.', 'sondern auch bleibt als feste Einheit zusammen.', 'Common Mistakes with Two-Part Connectors'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7244dacf-0a98-5c9c-a387-fa7e57ee6e64'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ce3995f5-453a-5dcf-9d4d-a2b6fa2ef1e4'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Firma / suchen / sowohl / eine Sekretärin / als auch / einen Techniker]', 'Write the sentence: The company is looking for both a secretary and a technician. (conjugate suchen for sie/es)', NULL, 'Die Firma sucht sowohl eine Sekretärin als auch einen Techniker.', '["Die Firma sucht sowohl eine Sekretärin als auch einen Techniker.","Die Firma sucht sowohl eine Sekretärin als auch einen Techniker"]'::jsonb, 'sucht is the correct sie-form of suchen.', 'sucht ist die richtige sie-Form von suchen.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sowohl and als auch stand directly before the two accusative objects.', 'sowohl und als auch stehen direkt vor den zwei Objekten im Akkusativ.', 'How to Join Two Words or Phrases'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ce3995f5-453a-5dcf-9d4d-a2b6fa2ef1e4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6406dd6b-a589-5917-b556-bbbceef57f1e'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Patientin / haben / weder / Fieber / noch / Schmerzen]', 'Write the sentence: The patient has neither fever nor pain. (conjugate haben for sie)', NULL, 'Die Patientin hat weder Fieber noch Schmerzen.', '["Die Patientin hat weder Fieber noch Schmerzen.","Die Patientin hat weder Fieber noch Schmerzen"]'::jsonb, 'hat is the sie-form of haben.', 'hat ist die sie-Form von haben.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'weder and noch stand directly before the two nouns.', 'weder und noch stehen direkt vor den zwei Nomen.', 'How to Join Two Words or Phrases'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6406dd6b-a589-5917-b556-bbbceef57f1e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ac025bfc-a4c8-5f74-b70a-1cf3bac2224f'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'multiple_choice', 'Eine Kollegin erzählt, wie ihr Chef sie kontaktiert: Was ist richtig?', 'A colleague describes how her boss contacts her: which sentence is correct? Either he calls me, or he writes an email.', '["Entweder ruft er mich an, oder er schreibt eine E-Mail.","Entweder ruft er mich an, aber er schreibt eine E-Mail.","Entweder ruft er mich an, oder schreibt er eine E-Mail.","Ruft entweder er mich an, oder er schreibt eine E-Mail."]'::jsonb, 'Entweder ruft er mich an, oder er schreibt eine E-Mail.', NULL, 'entweder opens the sentence, so ruft … an follows immediately; oder never triggers inversion in its own clause.', 'entweder steht am Anfang, ruft an steht direkt danach; oder löst in seinem eigenen Teil nie eine Inversion aus.', NULL, 12, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'entweder pairs only with oder (not aber), and after oder the normal order returns: er before schreibt.', 'entweder passt nur zu oder (nicht zu aber), und nach oder bleibt die normale Wortstellung: er vor schreibt.', 'Which Connectors Trigger Inversion?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ac025bfc-a4c8-5f74-b70a-1cf3bac2224f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b58a4668-baf5-5113-b379-0f70e0652cec'::uuid, 'dddf0703-5736-5297-900f-d7ab88d89923'::uuid, 5, 'multiple_choice', 'Auf der Reise: Was ist richtig?', 'While traveling: which sentence is correct? I need not only a passport, but also a visa.', '["Ich brauche nicht nur einen Pass, sondern auch ein Visum.","Ich brauche nicht nur einen Pass, sondern ein Visum auch.","Ich brauche nur nicht einen Pass, sondern auch ein Visum.","Ich brauche nicht nur einen Pass, aber auch ein Visum."]'::jsonb, 'Ich brauche nicht nur einen Pass, sondern auch ein Visum.', NULL, 'nicht nur … sondern auch stays together in this fixed order.', 'nicht nur … sondern auch bleibt als feste Reihenfolge zusammen.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other sentences change the word order or drop auch.', 'Die anderen Sätze verändern die Reihenfolge oder lassen auch weg.', 'Common Mistakes with Two-Part Connectors'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b58a4668-baf5-5113-b379-0f70e0652cec'::uuid);


